window.PJ_EX = [{"id":"Barbell_Squat","n":"Przysiad ze sztangą na plecach","en":"Barbell Squat","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","dolny odc. pleców"],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial","hipDeep","kneeStress","neckLoad"],"steps":["Ustaw sztangę w stojaku tuż poniżej wysokości barków i wejdź pod nią, kładąc ją na tylnej części barków.","Chwyć sztangę obiema rękami, zdejmij ją ze stojaka prostując nogi i tułów, po czym zrób krok w tył.","Stań na szerokość barków, palce lekko na zewnątrz, głowa uniesiona, plecy proste.","Powoli opuszczaj biodra i uginaj kolana, aż kąt w stawie kolanowym będzie nieco mniejszy niż 90 stopni. Wdech.","Wypchnij podłogę piętami, prostując nogi, i wróć do pozycji wyjściowej. Wydech."],"tips":["Kolana prowadź w linii palców stóp i nie pozwól im uciekać do środka.","Nie zaokrąglaj pleców i nie opuszczaj głowy; ćwicz w stojaku dla bezpieczeństwa."]},{"id":"Front_Squat_Clean_Grip","n":"Przysiad przedni ze sztangą","en":"Front Squat (Clean Grip)","p":"squat","m":["czworogłowe uda"],"m2":["brzuch","pośladki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","kneeStress","wristLoad"],"steps":["Ustaw sztangę w stojaku tuż poniżej barków i oprzyj ją na przednich naramiennych, lekko dotykając gardła.","Chwyć sztangę chwytem olimpijskim (clean), podtrzymując ją samymi palcami. Zdejmij ją ze stojaka i zrób krok w tył.","Stań na szerokość barków, palce lekko na zewnątrz, łokcie i głowa uniesione.","Ugnij kolana i usiądź głęboko między nogami, aż uda dotkną łydek.","Wypchnij podłogę środkiem stopy lub piętami i wstań do pozycji wyjściowej."],"tips":["Trzymaj łokcie wysoko, aby sztanga nie zsunęła się do przodu.","Kolana wypychaj na zewnątrz, w linii stóp."]},{"id":"Goblet_Squat","n":"Przysiad goblet","en":"Goblet Squat","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","barki"],"eq":"kettlebells","lvl":"beginner","u":"r","tags":[],"steps":["Stań prosto, trzymając lekki kettlebell za uchwyt tuż przy klatce piersiowej.","Zejdź w przysiadzie głęboko między nogami, aż uda dotkną łydek, z wyprostowanymi plecami i uniesioną głową.","W dolnej pozycji zatrzymaj się na chwilę i łokciami wypchnij kolana na zewnątrz.","Wróć do pozycji wyjściowej i powtórz 10-20 razy."],"tips":["Klatkę piersiową trzymaj wysoko, nie garb się.","Kettlebell przyciśnij do mostka przez cały ruch."]},{"id":"Bodyweight_Squat","n":"Przysiad bez obciążenia","en":"Bodyweight Squat","p":"squat","m":["czworogłowe uda"],"m2":["pośladki","dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Stań na szerokość barków, ręce możesz trzymać za głową.","Ugnij kolana i biodra, cofając pośladki jak do siadania.","Zejdź tak głęboko, jak pozwala mobilność, i dynamicznie wróć do pozycji wyjściowej."],"tips":["Głowę i klatkę piersiową trzymaj uniesione.","Kolana wypychaj na zewnątrz, nie pozwól im zapadać się do środka."]},{"id":"Chair_Squat","n":"Przysiad do krzesła","en":"Chair Squat","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw sztangę w stojaku na wysokość dopasowaną do wzrostu, wejdź pod nią i połóż ją na tylnej części barków.","Zdejmij sztangę prostując nogi i ustaw stopy na szerokość barków, ok. 45 cm przed sztangą, palce lekko na zewnątrz.","Patrz przed siebie, plecy w pozycji neutralnej lub lekko wygięte.","Powoli opuszczaj się, uginając kolana, aż kąt między udem a łydką będzie mniejszy niż 90 stopni.","Wypchnij podłogę piętami, prostując kolana, i wróć do pozycji wyjściowej."],"tips":["Utrzymuj neutralny kręgosłup, nie zaokrąglaj dolnego odcinka.","Ruch kontroluj, bez gwałtownego opadania."]},{"id":"Dumbbell_Squat","n":"Przysiad z hantlami","en":"Dumbbell Squat","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","dolny odc. pleców"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Stań prosto z hantlami w dłoniach, dłonie skierowane do ud, stopy na szerokość barków, palce lekko na zewnątrz.","Trzymaj głowę uniesioną i plecy proste, aby nie stracić równowagi.","Powoli opuszczaj tułów, uginając kolana, aż uda będą równoległe do podłogi. Wdech.","Wypchnij podłogę piętami, prostując nogi, i wróć na górę. Wydech."],"tips":["Kolana nie powinny wychodzić daleko przed palce stóp.","Nie opuszczaj głowy, bo to zaburza równowagę."]},{"id":"Dumbbell_Squat_To_A_Bench","n":"Przysiad z hantlami do ławki","en":"Dumbbell Squat To A Bench","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","dolny odc. pleców"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Stań tyłem do płaskiej ławki z hantlami w dłoniach, stopy na szerokość barków, palce lekko na zewnątrz.","Głowę trzymaj uniesioną, plecy proste.","Powoli uginaj kolana i opuszczaj tułów, aż lekko dotkniesz ławki pośladkami. Wdech.","Wypchnij podłogę piętami i wróć do pozycji wyjściowej. Wydech."],"tips":["Tylko lekko dotknij ławki, nie siadaj na niej całym ciężarem.","Kolana nie wychodzą przed palce stóp."]},{"id":"Box_Squat","n":"Przysiad do skrzyni","en":"Box Squat","p":"squat","m":["czworogłowe uda"],"m2":["przywodziciele","łydki","pośladki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","neckLoad"],"steps":["Ustaw skrzynię za sobą w stojaku, na wysokości zapewniającej przysiad do równoległości. Połóż sztangę na barkach, ściągnij łopatki i obróć łokcie do przodu.","Zdejmij sztangę, napnij lędźwia i cofnij się. Stopy szerzej angażują plecy, pośladki i przyciągacze, węziej czworogłowe.","Napnij plecy, barki i brzuch, wypchnij kolana na zewnątrz i usiądź biodrami na skrzyni.","Zatrzymaj się na skrzyni i rozluźnij zginacze bioder, bez odbijania się.","Dociskając pięty i wypychając kolana, wstań, utrzymując napięcie całego ciała."],"tips":["Nigdy nie odbijaj się od skrzyni.","Goleń powinna być ustawiona prostopadle do podłogi na dole ruchu."]},{"id":"Leg_Press","n":"Wypychanie nogami na suwnicy","en":"Leg Press","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na suwnicy i ustaw stopy na platformie na szerokość barków.","Zwolnij blokady i wypchnij platformę do pełnego wyprostu nóg, bez blokowania kolan. To pozycja wyjściowa.","Wdychając, powoli opuść platformę, aż kąt w kolanach wyniesie ok. 90 stopni.","Wydychając, wypchnij platformę piętami i czworogłowymi do pozycji wyjściowej.","Po serii koniecznie zabezpiecz platformę blokadami."],"tips":["Nie blokuj kolan w górnej pozycji.","Nie odrywaj pleców i bioder od oparcia."]},{"id":"Narrow_Stance_Leg_Press","n":"Suwnica – wąskie ustawienie stóp","en":"Narrow Stance Leg Press","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"intermediate","u":"r","tags":[],"steps":["Usiądź na suwnicy i ustaw stopy wąsko na platformie (do ok. 8 cm odstępu), palce lekko na zewnątrz.","Głowę trzymaj uniesioną, plecy cały czas oparte. Zwolnij blokady i wypchnij platformę bez blokowania kolan.","Wdychając, powoli opuść platformę do kąta 90 stopni w kolanach.","Wydychając, wypchnij platformę piętami do pozycji wyjściowej.","Po serii zabezpiecz platformę blokadami."],"tips":["Nie blokuj kolan na górze.","Plecy i pośladki przez cały czas przylegają do oparcia."]},{"id":"Hack_Squat","n":"Przysiad hack na maszynie","en":"Hack Squat","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"r","tags":["axial","kneeStress","neckLoad"],"steps":["Oprzyj plecy o oparcie maszyny i podłóż barki pod poduszki, stopy ustaw na platformie na szerokość barków.","Chwyć uchwyty, zwolnij blokady i wyprostuj nogi bez blokowania kolan.","Powoli uginaj kolana, opuszczając ciężar, aż uda znajdą się poniżej równoległości. Wdech.","Wypchnij platformę piętami, prostując nogi. Wydech."],"tips":["Plecy cały czas przylegają do oparcia, głowa uniesiona.","Kolana prowadź w linii palców stóp."]},{"id":"Smith_Machine_Squat","n":"Przysiad na maszynie Smitha","en":"Smith Machine Squat","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","dolny odc. pleców"],"eq":"machine","lvl":"beginner","u":"r","tags":["axial","neckLoad"],"steps":["Ustaw sztangę na odpowiedniej wysokości, wejdź pod nią i połóż ją na tylnej części barków.","Chwyć sztangę, odblokuj ją i wstań. Stopy na szerokość barków, palce lekko na zewnątrz, głowa uniesiona.","Powoli uginaj kolana, aż kąt między udem a łydką będzie nieco mniejszy niż 90 stopni. Wdech.","Wypchnij podłogę piętami, prostując nogi, i wróć do pozycji wyjściowej. Wydech."],"tips":["Dobierz ustawienie stóp tak, by kolana nie wychodziły daleko przed palce.","Nie zaokrąglaj pleców."]},{"id":"Front_Squats_With_Two_Kettlebells","n":"Przysiad przedni z dwoma kettlami","en":"Front Squats With Two Kettlebells","p":"squat","m":["czworogłowe uda"],"m2":["łydki","pośladki"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":[],"steps":["Podrzuć dwa kettlebelle na barki, prostując nogi i biodra oraz obracając nadgarstki.","Patrząc przed siebie, zejdź w przysiad jak najniżej i zatrzymaj się na dole.","Wypychaj kolana na zewnątrz, tułów trzymaj pionowo, głowę i klatkę piersiową uniesione.","Wstań, dociskając pięty, i powtórz."],"tips":["Nie pochylaj tułowia do przodu.","Łokcie trzymaj blisko ciała, a kettlebelle stabilnie na barkach."]},{"id":"Plie_Dumbbell_Squat","n":"Przysiad sumo z hantlem","en":"Plie Dumbbell Squat","p":"squat","m":["czworogłowe uda"],"m2":["brzuch","łydki","pośladki","dwugłowe uda"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["hipDeep"],"steps":["Chwyć hantel obiema rękami za jego koniec i stań prosto.","Rozstaw nogi szerzej niż barki, kolana lekko ugięte, palce skierowane na zewnątrz. Ramiona pozostają nieruchome.","Powoli uginaj kolana, aż uda będą równoległe do podłogi. Wdech.","Wypchnij podłogę piętami i wróć do pozycji wyjściowej. Wydech."],"tips":["Kolana prowadź w kierunku palców stóp.","Tułów trzymaj pionowo, ramiona nie pracują."]},{"id":"Dumbbell_Lunges","n":"Wykroki z hantlami","en":"Dumbbell Lunges","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["kneeStress"],"steps":["Stań prosto z hantlami w dłoniach po bokach ciała.","Zrób duży krok prawą nogą do przodu (ok. 60 cm) i opuść ciało, zachowując pionowy tułów i równowagę. Wdech.","Goleń przedniej nogi ma być prostopadła do podłogi.","Odepchnij się piętą i wróć do pozycji wyjściowej. Wydech.","Powtórz serię, po czym wykonaj ją drugą nogą."],"tips":["Kolano nie powinno wychodzić daleko przed palce stopy.","Tułów trzymaj pionowo, bez pochylania."]},{"id":"Dumbbell_Rear_Lunge","n":"Wykroki w tył z hantlami","en":"Dumbbell Rear Lunge","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Stań prosto z hantlami w dłoniach po bokach ciała.","Zrób krok prawą nogą do tyłu (ok. 60 cm) i opuść ciało, zachowując pionowy tułów. Wdech.","Długi krok mocniej angażuje pośladki, krótki czworogłowe.","Wróć do pozycji wyjściowej, odpychając się przednią nogą. Wydech.","Powtórz na drugą nogę."],"tips":["Przednia goleń pozostaje prostopadła do podłogi.","Aby zaakcentować pośladki, dociskaj piętę, a dla czworogłowych palce stopy."]},{"id":"Barbell_Lunge","n":"Wykroki ze sztangą","en":"Barbell Lunge","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","kneeStress","neckLoad"],"steps":["Ustaw sztangę w stojaku tuż poniżej barków, wejdź pod nią i połóż ją na tylnej części barków. Najlepiej ćwiczyć w stojaku.","Zdejmij sztangę ze stojaka i zrób krok w tył.","Zrób krok prawą nogą do przodu i opuść biodra, utrzymując pionowy tułów. Wdech.","Odepchnij się piętą i wróć do pozycji wyjściowej. Wydech.","Powtórz serię, po czym zmień nogę."],"tips":["Kolano nie powinno wychodzić daleko przed palce stopy.","Zachowaj równowagę i prosty tułów."]},{"id":"Barbell_Walking_Lunge","n":"Wykroki chodzone ze sztangą","en":"Barbell Walking Lunge","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial","kneeStress","neckLoad"],"steps":["Stań na szerokość barków ze sztangą na górnej części pleców.","Zrób krok do przodu i ugnij kolana, opuszczając biodra, aż tylne kolano prawie dotknie podłogi.","Tułów trzymaj pionowo, przednie kolano nad stopą.","Odepchnij się piętą przedniej nogi i wyprostuj obie nogi.","Przenieś tylną nogę do przodu i powtórz wykrok na drugą stronę."],"tips":["Przednie kolano ma pozostać nad stopą.","Nie pochylaj się do przodu pod ciężarem sztangi."]},{"id":"Bodyweight_Walking_Lunge","n":"Wykroki chodzone bez obciążenia","en":"Bodyweight Walking Lunge","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":["kneeStress"],"steps":["Stań na szerokość barków, dłonie oprzyj na biodrach.","Zrób krok do przodu i ugnij kolana, aż tylne kolano prawie dotknie podłogi.","Tułów trzymaj pionowo, przednie kolano nad stopą.","Odepchnij się piętą przedniej nogi i wyprostuj nogi.","Przenieś tylną nogę do przodu i powtórz wykrok na drugą stronę."],"tips":["Przednie kolano nie zapada się do środka.","Utrzymuj pionową sylwetkę i krok o stałej długości."]},{"id":"Split_Squat_with_Dumbbells","n":"Przysiad wykroczny z hantlami","en":"Split Squat with Dumbbells","p":"lunge","m":["czworogłowe uda"],"m2":["pośladki","dwugłowe uda"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Przyjmij pozycję wykroczną z tylną stopą uniesioną na podwyższeniu, a przednią przed sobą.","Trzymaj hantle w opuszczonych rękach po bokach.","Ugnij kolano i biodro, opuszczając ciało w dół, z zachowaniem prawidłowej postawy.","W dolnej pozycji odepchnij się piętą i wyprostuj kolano i biodro."],"tips":["Przednie kolano prowadź w linii stopy.","Tułów utrzymuj stabilnie, bez przechylania."]},{"id":"Dumbbell_Step_Ups","n":"Wejścia na skrzynię z hantlami","en":"Dumbbell Step Ups","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Stań prosto, trzymając hantle w dłoniach po bokach ciała. Przed sobą ustaw podwyższenie.","Postaw prawą stopę na podwyższeniu i wejdź, prostując biodro i kolano, głównie dociskając piętę. Wydech.","Dostaw lewą stopę na górze.","Zejdź lewą nogą, uginając prawe biodro i kolano. Wdech. Wróć do pozycji wyjściowej.","Powtórz serię prawą nogą, po czym wykonaj ją lewą."],"tips":["Pracuj nogą stojącą na podwyższeniu, nie odpychaj się drugą.","Tułów trzymaj prosto."]},{"id":"Barbell_Step_Ups","n":"Wejścia na skrzynię ze sztangą","en":"Barbell Step Ups","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","czworogłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","kneeStress","neckLoad"],"steps":["Stań prosto ze sztangą na tylnej części barków, za podwyższeniem (np. ławką).","Postaw prawą stopę na podwyższeniu i wejdź, prostując biodro i kolano, głównie dociskając piętę. Wydech.","Dostaw lewą stopę na górze.","Zejdź lewą nogą, uginając prawe biodro i kolano. Wdech. Wróć do pozycji wyjściowej.","Powtórz serię prawą nogą, po czym wykonaj ją lewą."],"tips":["Dobierz wysokość podwyższenia tak, by kolano nie było zgięte poniżej 90 stopni.","Utrzymuj sztangę stabilnie i tułów prosto."]},{"id":"Elevated_Back_Lunge","n":"Wykrok w tył z podwyższenia","en":"Elevated Back Lunge","p":"lunge","m":["czworogłowe uda"],"m2":["pośladki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["hipDeep","kneeStress"],"steps":["Ustaw sztangę w stojaku na wysokości barków i załaduj ją. Za sobą połóż niską platformę.","Zdejmij sztangę na górną część pleców z napiętym, lekko wygiętym grzbietem. Wejdź obiema stopami na platformę.","Zrób krok jedną nogą w tył i opuść się, uginając biodra i kolana, aż tylne kolano dotknie podłogi.","Zatrzymaj się na chwilę, po czym wyprostuj biodra i kolana i wróć na platformę.","Zmieniaj nogi."],"tips":["Plecy trzymaj napięte przez cały ruch.","Wróć całkowicie do pozycji wyjściowej przed zmianą nogi."]},{"id":"Smith_Single-Leg_Split_Squat","n":"Przysiad bułgarski na Smithie","en":"Smith Single-Leg Split Squat","p":"lunge","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"r","tags":["kneeStress"],"steps":["Ustaw płaską ławkę 60-90 cm za maszyną Smitha, a sztangę na odpowiedniej wysokości.","Wejdź pod sztangę, połóż ją na tylnej części barków, odblokuj i wstań.","Jedną stopę ustaw lekko z przodu pod sztangą, drugą nogę odstaw do tyłu, kładąc podbicie na ławce.","Powoli ugnij kolano, aż kąt między udem a łydką będzie nieco mniejszy niż 90 stopni. Wdech.","Wypchnij podłogę piętą, prostując nogę. Wydech. Po serii zmień nogę."],"tips":["Przednie kolano nie powinno wychodzić daleko przed palce.","Głowa uniesiona, plecy proste."]},{"id":"Step-up_with_Knee_Raise","n":"Wejście na stopień z unoszeniem kolana","en":"Step-up with Knee Raise","p":"lunge","m":["pośladki"],"m2":["dwugłowe uda","czworogłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":["kneeStress"],"steps":["Stań przodem do skrzyni lub ławki o odpowiedniej wysokości, stopy razem.","Wejdź lewą stopą na skrzynię, prostując biodro i kolano nogi wchodzącej.","Gdy stoisz na lewej nodze, ugnij prawe kolano i biodro, unosząc kolano jak najwyżej.","Odwróć ruch, zejdź ze skrzyni i powtórz na drugą nogę."],"tips":["Kontroluj ruch, nie nabieraj rozpędu.","Utrzymuj stabilną równowagę na górze."]},{"id":"Split_Squats","n":"Przysiad wykroczny bez obciążenia","en":"Split Squats","p":"lunge","m":["dwugłowe uda"],"m2":["łydki","pośladki","czworogłowe uda"],"eq":"body only","lvl":"intermediate","u":"r","tags":[],"steps":["Stań prosto.","Wyskocz do pozycji wykrocznej, jedna noga z przodu, druga z tyłu, uginając kolana i lekko opuszczając biodra.","Natychmiast odwróć ruch, wstań i wyskokiem zamień nogi.","Powtórz 5-10 razy na każdą nogę."],"tips":["Ląduj miękko, na lekko ugiętych nogach.","Tułów trzymaj pionowo, przednie kolano nad stopą."]},{"id":"Barbell_Deadlift","n":"Martwy ciąg klasyczny","en":"Barbell Deadlift","p":"hinge","m":["dolny odc. pleców"],"m2":["łydki","przedramiona","pośladki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial"],"steps":["Stań przed załadowaną sztangą. Z prostymi plecami ugnij kolana, pochyl się i chwyć sztangę nachwytem na szerokość barków.","Wydychając, unieś sztangę, prostując nogi i tułów jednocześnie.","W górnej pozycji wypchnij klatkę i ściągnij łopatki, jak żołnierz na baczność.","Wróć, uginając kolana i pochylając tułów przy prostych plecach, aż talerze dotkną podłogi."],"tips":["Nigdy nie zaokrąglaj pleców.","Jeśli chwyt zawodzi, użyj chwytu mieszanego lub pasków."]},{"id":"Romanian_Deadlift","n":"Rumuński martwy ciąg","en":"Romanian Deadlift","p":"hinge","m":["dwugłowe uda"],"m2":["łydki","pośladki","dolny odc. pleców"],"eq":"barbell","lvl":"intermediate","u":"r","tags":[],"steps":["Połóż sztangę przed sobą i chwyć ją nachwytem nieco szerzej niż barki. W razie potrzeby użyj pasków.","Lekko ugnij kolana, goleń trzymaj pionowo, biodra cofnięte, plecy proste. To pozycja wyjściowa.","Z prostymi plecami i rękami unieś sztangę, napinając biodra, aż staniesz prosto. Wydech.","Opuść sztangę, cofając biodra i tylko lekko uginając kolana, w przeciwieństwie do przysiadu. Wdech na początku i zatrzymanie oddechu przy opuszczaniu."],"tips":["Ruch ma być wolny i kontrolowany.","Klatkę trzymaj uniesioną, plecy proste."]},{"id":"Stiff-Legged_Dumbbell_Deadlift","n":"Martwy ciąg na prostych nogach z hantlami","en":"Stiff-Legged Dumbbell Deadlift","p":"hinge","m":["dwugłowe uda"],"m2":["pośladki","dolny odc. pleców"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Chwyć hantle po bokach ciała w opuszczonych rękach.","Stań prosto na szerokość barków lub węziej, z lekko ugiętymi kolanami.","Nie zmieniając kąta kolan, pochyl się w biodrach z prostymi plecami i opuść hantle nad stopy, aż poczujesz rozciąganie dwugłowych. Wydech.","Wyprostuj biodra i tułów do pozycji wyjściowej. Wdech."],"tips":["Plecy muszą pozostać proste.","Kolana trzymaj nieruchomo, ruch wykonuj w biodrach."]},{"id":"Trap_Bar_Deadlift","n":"Martwy ciąg z trap bar","en":"Trap Bar Deadlift","p":"hinge","m":["czworogłowe uda"],"m2":["pośladki","dwugłowe uda"],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial"],"steps":["Załaduj sztangę trap bar (hex) i połóż ją na podłodze. Stań w jej środku i chwyć oba uchwyty.","Obniż biodra, patrz przed siebie, klatka piersiowa uniesiona.","Dociśnij pięty i wyprostuj biodra oraz kolana.","Kontrolowanie opuść ciężar na podłogę."],"tips":["Nie zaokrąglaj pleców w żadnym momencie.","Ciężar opuszczaj pod kontrolą, nie rzucaj."]},{"id":"Sumo_Deadlift","n":"Martwy ciąg sumo","en":"Sumo Deadlift","p":"hinge","m":["dwugłowe uda"],"m2":["przywodziciele","przedramiona","pośladki","dolny odc. pleców"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","hipDeep"],"steps":["Ustaw sztangę na podłodze tak, aby przecinała środek stóp, a nogi rozstaw bardzo szeroko, blisko zacisków.","Pochyl się w biodrach i chwyć sztangę z rękami pod barkami, wewnątrz nóg, chwytem nachwytem, mieszanym lub hakowym.","Weź oddech, obniż biodra, patrz przed siebie, klatka uniesiona.","Dociskaj podłogę, rozpychając stopy na boki, ciężar na tylnej części stóp, i prostuj biodra i kolana.","Gdy sztanga minie kolana, odchyl się i wepchnij biodra w sztangę, ściągając łopatki. Opuść sztangę pod kontrolą."],"tips":["Kolana prowadź na zewnątrz w linii stóp.","Ciężar trzymaj na tylnej połowie stóp."]},{"id":"Rack_Pulls","n":"Martwy ciąg z podwyższenia (rack pull)","en":"Rack Pulls","p":"hinge","m":["dolny odc. pleców"],"m2":["przedramiona","pośladki","dwugłowe uda","kaptury"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial"],"steps":["Ustaw sztangę na kołkach w stojaku na wybranej wysokości: tuż pod kolanami, nad nimi lub w połowie uda.","Ustaw się jak do martwego ciągu: stopy pod biodrami, chwyt na szerokość barków, plecy wygięte, biodra cofnięte.","Przy dużym ciężarze użyj chwytu mieszanego, hakowego lub pasków.","Patrząc przed siebie, wyprostuj biodra i kolana, ciągnąc sztangę w górę i do tyłu aż do pełnego wyprostu, ściągając barki.","Odłóż sztangę na kołki i powtórz."],"tips":["Nie zaokrąglaj pleców.","Na końcu ruchu ściągnij barki do tyłu."]},{"id":"Kettlebell_One-Legged_Deadlift","n":"Martwy ciąg na jednej nodze z kettlem","en":"Kettlebell One-Legged Deadlift","p":"hinge","m":["dwugłowe uda"],"m2":["pośladki","dolny odc. pleców"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":[],"steps":["Chwyć kettlebell jedną ręką za uchwyt i stań na nodze po tej samej stronie.","Utrzymując lekko ugięte kolano, pochyl się w biodrze jak w martwym ciągu na prostych nogach, a wolną nogę wyprostuj do tyłu dla równowagi.","Opuszczaj kettlebell, aż tułów będzie równoległy do podłogi.","Wróć do pozycji wyprostowanej."],"tips":["Biodra trzymaj prosto, nie obracaj miednicy.","Plecy proste, wzrok skierowany w dół przed siebie."]},{"id":"One-Arm_Kettlebell_Swings","n":"Swing kettlem jednorącz","en":"One-Arm Kettlebell Swings","p":"hinge","m":["dwugłowe uda"],"m2":["łydki","pośladki","dolny odc. pleców","barki"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":["highIntensity"],"steps":["Stań szerzej niż barki, kettlebell postaw przed sobą i chwyć go jedną ręką.","Odchyl kettlebell między nogi, cofając biodra, plecy proste.","Dynamicznie wyprostuj biodra, aby wyrzucić kettlebell do wysokości barków.","Pozwól mu opaść i płynnie wróć między nogi, powtarzając ruch."],"tips":["Ruch pochodzi z bioder, nie z ramienia.","Plecy proste, nie zaokrąglaj ich przy zamachu."]},{"id":"Good_Morning","n":"Dzień dobry ze sztangą","en":"Good Morning","p":"hinge","m":["dwugłowe uda"],"m2":["brzuch","pośladki","dolny odc. pleców"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","neckLoad","spinalFlex"],"steps":["Ustaw sztangę w stojaku na wysokości barków. Połóż ją na tylnej części barków jak do przysiadu, nie na karku.","Napnij plecy, ściągnij łopatki, lekko ugnij kolana i zrób krok w tył.","Pochyl się w biodrach, cofając je, do pozycji niemal równoległej, z wygiętymi plecami i utrzymanym kręgosłupem szyjnym.","Wyprostuj biodra pracą pośladków i dwugłowych, wracając do pozycji wyjściowej."],"tips":["Plecy cały czas wygięte, bez zaokrąglania.","Użyj lżejszego ciężaru i kontroluj tempo."]},{"id":"Barbell_Hip_Thrust","n":"Hip thrust ze sztangą","en":"Barbell Hip Thrust","p":"hinge","m":["pośladki"],"m2":["łydki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":[],"steps":["Usiądź na podłodze z ławką za plecami i załadowaną sztangą nad nogami. Dla komfortu użyj podkładki na sztangę.","Przetocz sztangę na biodra i oprzyj łopatki o górną krawędź ławki.","Dociskając stopy, wyprostuj biodra pionowo, unosząc sztangę. Ciężar spoczywa na łopatkach i stopach.","Wyprostuj biodra maksymalnie, po czym wróć do pozycji wyjściowej."],"tips":["Na górze napnij pośladki, nie wyginaj lędźwi.","Broda lekko przyciągnięta, wzrok przed siebie."]},{"id":"Barbell_Glute_Bridge","n":"Most biodrowy ze sztangą","en":"Barbell Glute Bridge","p":"hinge","m":["pośladki"],"m2":["łydki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":[],"steps":["Usiądź na podłodze z załadowaną sztangą nad nogami. Dla komfortu użyj podkładki.","Przetocz sztangę na biodra i połóż się płasko na plecach.","Dociskając pięty, wyprostuj biodra pionowo przez sztangę. Ciężar spoczywa na górnej części pleców i piętach.","Wyprostuj biodra maksymalnie, po czym wróć do pozycji wyjściowej."],"tips":["Ruch wykonuj pośladkami, nie lędźwiami.","Pięty mocno dociskaj do podłogi."]},{"id":"Butt_Lift_Bridge","n":"Most biodrowy","en":"Butt Lift (Bridge)","p":"hinge","m":["pośladki"],"m2":["dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na plecach z rękami wzdłuż ciała i ugiętymi kolanami, stopy na szerokość barków.","Dociskając głównie pięty, unieś biodra z podłogi, utrzymując proste plecy. Wydech.","Zatrzymaj się na górze na sekundę.","Powoli wróć do pozycji wyjściowej. Wdech."],"tips":["Napnij pośladki na górze.","Nie przeprostowuj odcinka lędźwiowego."]},{"id":"Single_Leg_Glute_Bridge","n":"Most biodrowy jednonóż","en":"Single Leg Glute Bridge","p":"hinge","m":["pośladki"],"m2":["dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na plecach, stopy płasko, kolana ugięte.","Unieś jedną nogę nad podłogę i przyciągnij kolano do klatki piersiowej.","Dociskając piętę drugiej nogi, wyprostuj biodro i unieś pośladki z podłogi.","Wyprostuj biodro maksymalnie, zatrzymaj się i wróć do pozycji wyjściowej."],"tips":["Biodra trzymaj poziomo, nie opadaj na bok.","Ruch wykonuj pośladkiem, nie plecami."]},{"id":"Pull_Through","n":"Przeciąganie liny między nogami (pull through)","en":"Pull Through","p":"hinge","m":["pośladki"],"m2":["dwugłowe uda","dolny odc. pleców"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań kilka kroków przed dolnym wyciągiem z linką lub uchwytem, tyłem do maszyny, z liną między nogami i szeroko rozstawionymi stopami.","Pochyl się w biodrach, sięgając rękami jak najdalej między nogami, kolana lekko ugięte.","Z prostymi rękami wyprostuj biodra, aby stanąć prosto.","Wróć do pozycji wyjściowej kontrolowanym ruchem."],"tips":["Ruch pochodzi z bioder, nie z barków.","Ręce są proste, plecy bez zaokrąglania."]},{"id":"Hyperextensions_Back_Extensions","n":"Wyprosty tułowia na ławce rzymskiej","en":"Hyperextensions (Back Extensions)","p":"hinge","m":["dolny odc. pleców"],"m2":["pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"r","tags":["headDown"],"steps":["Połóż się twarzą w dół na ławce rzymskiej i zaklinuj kostki pod wałkami. Ustaw podkładkę tak, aby biodra mogły się swobodnie zginać.","Skrzyżuj ręce na piersi lub za głową. Ciało wyprostowane to pozycja wyjściowa.","Powoli pochyl się w pasie, utrzymując plecy płaskie, aż poczujesz rozciąganie dwugłowych. Wdech.","Powoli unieś tułów do pozycji wyjściowej."],"tips":["Nie zaokrąglaj pleców ani nie wyginaj ich poza linię prostą.","Nie bujaj tułowiem."]},{"id":"Band_Good_Morning","n":"Dzień dobry z gumą","en":"Band Good Morning","p":"hinge","m":["dwugłowe uda"],"m2":["pośladki","dolny odc. pleców"],"eq":"bands","lvl":"beginner","u":"r","tags":["axial"],"steps":["Stań na jednym końcu gumy (ok. 104 cm), stopy lekko rozstaw.","Pochyl się w biodrach i załóż drugi koniec gumy na kark. To pozycja wyjściowa.","Z prostymi nogami wyprostuj biodra do pozycji niemal pionowej.","Wróć do pozycji wyjściowej, nie zaokrąglając pleców."],"tips":["Plecy cały czas proste.","Ruch wykonuj w biodrach, nogi pozostają proste."]},{"id":"Leg_Extensions","n":"Prostowanie nóg na maszynie","en":"Leg Extensions","p":"legiso","m":["czworogłowe uda"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":["kneeStress"],"steps":["Wybierz ciężar i usiądź na maszynie z nogami pod wałkiem, stopami do przodu, trzymając boczne uchwyty.","Ustaw wałek na dolnej części goleni, tuż nad stopami, a kąt w kolanach na 90 stopni.","Wydychając, wyprostuj nogi maksymalnie siłą czworogłowych, bez ruchu reszty ciała.","Zatrzymaj się sekundę w napięciu, po czym powoli opuść ciężar. Wdech, nie schodząc poniżej 90 stopni."],"tips":["Nie odrywaj pośladków od siedziska.","Opuszczaj ciężar powoli, bez szarpania."]},{"id":"Lying_Leg_Curls","n":"Uginanie nóg leżąc na maszynie","en":"Lying Leg Curls","p":"legiso","m":["dwugłowe uda"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw maszynę do swojego wzrostu i połóż się twarzą w dół, wałek na tylnej części nóg, kilka centymetrów pod łydkami.","Utrzymując płasko tułów, wyprostuj nogi i chwyć boczne uchwyty. Palce stóp skierowane prosto.","Wydychając, ugnij nogi jak najmocniej, nie unosząc ud z ławki.","Zatrzymaj się sekundę w pełnym napięciu i powoli wróć. Wdech."],"tips":["Nie unoś bioder z ławki.","Ruch wykonuj płynnie, bez szarpania."]},{"id":"Seated_Leg_Curl","n":"Uginanie nóg siedząc na maszynie","en":"Seated Leg Curl","p":"legiso","m":["dwugłowe uda"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw maszynę do swojego wzrostu i usiądź plecami do oparcia. Tylną część dolnej nogi połóż na wałku, kilka centymetrów pod łydkami.","Zabezpiecz uda wałkiem tuż nad kolanami i chwyć boczne uchwyty. Nogi wyprostowane przed sobą.","Wydychając, przyciągnij wałek jak najbliżej tylnej części ud, uginając kolana.","Zatrzymaj się sekundę w napięciu i powoli wróć. Wdech."],"tips":["Tułów trzymaj nieruchomo.","Opuszczaj ciężar powoli."]},{"id":"Ball_Leg_Curl","n":"Uginanie nóg na piłce","en":"Ball Leg Curl","p":"legiso","m":["dwugłowe uda"],"m2":["łydki","pośladki"],"eq":"exercise ball","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na plecach z piętami na piłce, tak aby przy wyprostowanych nogach kostki spoczywały na jej górze.","Unieś biodra nad podłogę, opierając ciężar na łopatkach i stopach.","Ugnij kolana, przyciągając piłkę jak najbliżej siebie i napinając dwugłowe uda.","Po krótkiej pauzie wróć do pozycji wyjściowej."],"tips":["Biodra trzymaj wysoko przez cały ruch.","Kontroluj piłkę, nie pozwól jej uciekać na boki."]},{"id":"Thigh_Abductor","n":"Odwodzenie nóg na maszynie","en":"Thigh Abductor","p":"legiso","m":["odwodziciele"],"m2":["pośladki"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na maszynie do odwodzenia i dobierz komfortowy ciężar.","Chwyć uchwyty po bokach i ustaw nogi na wałkach. Górną część ciała trzymaj nieruchomo.","Wydychając, powoli rozsuwaj nogi na boki.","Zatrzymaj się sekundę w napięciu i wróć do pozycji wyjściowej. Wdech."],"tips":["Tułów pozostaje nieruchomy.","Nie szarp ciężarem."]},{"id":"Thigh_Adductor","n":"Przywodzenie nóg na maszynie","en":"Thigh Adductor","p":"legiso","m":["przywodziciele"],"m2":["pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na maszynie do przywodzenia i dobierz komfortowy ciężar.","Ustaw nogi na wałkach, chwyć uchwyty po bokach i trzymaj górną część ciała nieruchomo.","Wydychając, powoli zbliżaj nogi do siebie.","Zatrzymaj się sekundę w napięciu i wróć do pozycji wyjściowej. Wdech."],"tips":["Unikaj gwałtownych, szarpanych ruchów.","Tułów pozostaje nieruchomy."]},{"id":"Glute_Kickback","n":"Wymachy nogi w tył w klęku","en":"Glute Kickback","p":"legiso","m":["pośladki"],"m2":["dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Uklęknij na macie i pochyl się w pasie, wyciągając ręce przed siebie na szerokość barków, jak do pompki w klęku. Głowa patrzy przed siebie.","Kolana ugięte pod kątem 90 stopni między udem a łydką.","Wydychając, unieś prawą nogę, aż udo znajdzie się w linii pleców, zachowując kąt 90 stopni. Napnij pośladek.","Zatrzymaj się sekundę na górze, po czym wróć. Wdech. Powtórz drugą nogą, zmieniając je na przemian."],"tips":["Udo na górze jest równoległe do podłogi, a łydka prostopadła.","Nie wyginaj lędźwi, ruch wykonuj pośladkiem."]},{"id":"One-Legged_Cable_Kickback","n":"Wymachy nogi w tył na wyciągu","en":"One-Legged Cable Kickback","p":"legiso","m":["pośladki"],"m2":["dwugłowe uda"],"eq":"cable","lvl":"intermediate","u":"r","tags":[],"steps":["Przypnij skórzany pasek do kostki i podłącz go do dolnego wyciągu.","Stań twarzą do stosu ciężarów w odległości ok. 60 cm, trzymając się ramy dla podparcia.","Z lekko ugiętymi kolanami i biodrami oraz napiętym brzuchem, napinając pośladek, wykonaj powolny wymach nogi w tył po półkolistym łuku, tak wysoko, jak to komfortowe. Wydech.","Na szczycie ściśnij pośladek na sekundę.","Powoli przenieś nogę do przodu, stawiając opór wyciągowi. Powtórz, po czym zmień nogę."],"tips":["Ruch pochodzi z biodra, nie z lędźwi.","Brzuch napięty, tułów stabilny."]},{"id":"Monster_Walk","n":"Chód potwora z gumą","en":"Monster Walk","p":"legiso","m":["odwodziciele"],"m2":[],"eq":"bands","lvl":"beginner","u":"r","tags":[],"steps":["Załóż jedną gumę wokół kostek, a drugą nad kolanami. Ustaw stopy na szerokość barków tak, by guma była napięta.","Rób krótkie kroki do przodu, naprzemiennie lewą i prawą nogą.","Po kilku krokach wróć tą samą drogą, idąc tyłem."],"tips":["Utrzymuj stałe napięcie gumy, nie ściągaj stóp razem.","Nie kołysz tułowia i nie pozwól kolanom zapadać się do środka."]},{"id":"Standing_Calf_Raises","n":"Wspięcia na palce stojąc","en":"Standing Calf Raises","p":"calves","m":["łydki"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw wysokość poduszek maszyny odpowiednio do wzrostu.","Podłóż barki pod poduszki, a przodostopia oprzyj na podeście, pięty zwisają. Wyprostuj biodra i kolana, kolana lekko ugięte.","Na wydechu unieś pięty jak najwyżej, napinając łydki. Zatrzymaj się na sekundę.","Wdychając, powoli opuść pięty do pełnego rozciągnięcia łydek.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie uginaj kolan w trakcie ruchu, pracują tylko kostki.","Nie podskakuj, kontroluj zwłaszcza fazę opuszczania."]},{"id":"Seated_Calf_Raise","n":"Wspięcia na palce siedząc","en":"Seated Calf Raise","p":"calves","m":["łydki"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na maszynie, przodostopia oprzyj na platformie, pięty zwisają. Ustaw palce w wybranej pozycji.","Podłóż dolne partie ud pod poduszkę i dopasuj jej wysokość. Dłonie połóż na poduszce, by się nie przesuwała.","Unieś pięty, zwolnij blokadę bezpieczeństwa i wyjdź z pozycji startowej.","Wdychając, powoli opuść pięty do pełnego rozciągnięcia łydek.","Na wydechu unieś pięty jak najwyżej i zatrzymaj się na sekundę.","Powtórz zaplanowaną liczbę razy."],"tips":["Ruch wykonuj tylko w kostkach, bez odbijania się.","Nie skracaj zakresu, na dole pełne rozciągnięcie."]},{"id":"Standing_Dumbbell_Calf_Raise","n":"Wspięcia na palce z hantlami","en":"Standing Dumbbell Calf Raise","p":"calves","m":["łydki"],"m2":[],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Stań wyprostowany z hantlami w opuszczonych rękach. Przodostopia oprzyj na stabilnym podwyższeniu (2-3 cm wyżej), pięty zwisają.","Na wydechu unieś pięty, napinając łydki, i przytrzymaj sekundę. Palce na zewnątrz akcentują wewnętrzną głowę, do wewnątrz zewnętrzną.","Wdychając, powoli opuść pięty.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie bujaj tułowiem, utrzymaj sylwetkę prosto.","Zatrzymuj się u góry i nie opuszczaj pięt zbyt szybko."]},{"id":"Calf_Press_On_The_Leg_Press_Machine","n":"Wspięcia na palce na suwnicy","en":"Calf Press On The Leg Press Machine","p":"calves","m":["łydki"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na suwnicy i ustaw stopy na platformie na szerokość barków.","Zwolnij blokady i wypchnij platformę do prostych nóg bez blokowania kolan. Przodostopia oprzyj na dolnej części platformy, pięty zwisają.","Na wydechu unieś pięty jak najwyżej, napinając łydki, i zatrzymaj się na sekundę.","Wdychając, powoli opuść pięty do rozciągnięcia łydek.","Powtórz zaplanowaną liczbę razy."],"tips":["Kolana pozostają nieruchome i nie są zablokowane.","Pracuj wolno, bez odbijania platformy."]},{"id":"Barbell_Bench_Press_-_Medium_Grip","n":"Wyciskanie sztangi na ławce płaskiej","en":"Barbell Bench Press - Medium Grip","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"barbell","lvl":"beginner","u":"r","tags":["shoulderStress"],"steps":["Połóż się na ławce płaskiej. Chwyć sztangę średnim chwytem (kąt 90 stopni w łokciach w połowie ruchu), zdejmij ją ze stojaka i trzymaj nad sobą na prostych rękach.","Wdychając, powoli opuść sztangę do środka klatki piersiowej.","Po krótkiej pauzie wypchnij sztangę w górę na wydechu, napinając klatkę.","Na górze wyprostuj ręce, zatrzymaj sekundę i znów opuszczaj.","Po serii odłóż sztangę na stojak."],"tips":["Opuszczanie powinno trwać około dwa razy dłużej niż wyciskanie.","Nie odbijaj sztangi od klatki i nie odrywaj pośladków od ławki."]},{"id":"Dumbbell_Bench_Press","n":"Wyciskanie hantli na ławce płaskiej","en":"Dumbbell Bench Press","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na ławce płaskiej z hantlami na udach, dłonie zwrócone do siebie.","Pomagając sobie udami, unoś hantle po kolei i trzymaj je przed sobą na szerokość barków.","Obróć nadgarstki tak, by dłonie były skierowane od ciebie. Hantle są przy bokach klatki, kąt w łokciu 90 stopni.","Na wydechu wypchnij hantle w górę siłą klatki, wyprostuj ręce i zatrzymaj sekundę.","Powoli opuść ciężar. Powtórz zaplanowaną liczbę razy."],"tips":["Opuszczanie powinno trwać około dwa razy dłużej niż wyciskanie.","Zawsze kontroluj hantle, nie pozwól im odpływać na boki."]},{"id":"Incline_Dumbbell_Press","n":"Wyciskanie hantli na ławce skośnej","en":"Incline Dumbbell Press","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na ławce skośnej z hantlami na udach, dłonie zwrócone do siebie.","Pomagając sobie udami, unoś hantle po kolei na szerokość barków.","Obróć nadgarstki tak, by dłonie były skierowane od ciebie. To pozycja startowa.","Na wydechu wypchnij hantle w górę siłą klatki. Wyprostuj ręce, zatrzymaj sekundę i powoli opuszczaj.","Po serii odłóż hantle na uda, a potem na podłogę."],"tips":["Opuszczanie powinno trwać około dwa razy dłużej niż wyciskanie.","Nie ściągaj hantli zbyt nisko ani zbyt szybko, kontroluj tor ruchu."]},{"id":"Barbell_Incline_Bench_Press_-_Medium_Grip","n":"Wyciskanie sztangi na ławce skośnej","en":"Barbell Incline Bench Press - Medium Grip","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"barbell","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na ławce skośnej. Chwyć sztangę średnim chwytem, zdejmij ją ze stojaka i trzymaj nad sobą na prostych rękach.","Wdychając, powoli opuść sztangę do górnej części klatki piersiowej.","Po sekundowej pauzie wypchnij sztangę w górę na wydechu siłą klatki.","Wyprostuj ręce, zatrzymaj sekundę i powoli opuszczaj.","Po serii odłóż sztangę na stojak."],"tips":["Opuszczanie powinno trwać co najmniej dwa razy dłużej niż wyciskanie.","Nie odbijaj sztangi od klatki i nie wyginaj mocno pleców."]},{"id":"Machine_Bench_Press","n":"Wyciskanie na maszynie siedząc","en":"Machine Bench Press","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na maszynie do wyciskania i wybierz obciążenie.","Użyj dźwigni nożnej, by przesunąć uchwyty do przodu, chwyć je nachwytem i podnieś łokcie tak, by ramiona były równoległe do podłogi.","Wyprostuj ręce - to pozycja startowa.","Wdychając, powoli przyciągnij uchwyty do siebie.","Na wydechu wypchnij uchwyty, napinając klatkę, i zatrzymaj sekundę.","Powtórz zaplanowaną liczbę razy, a na koniec odłóż uchwyty dźwignią nożną."],"tips":["Plecy trzymaj oparte o oparcie, bez odrywania łopatek.","Nie blokuj łokci na siłę i nie rzucaj ciężarem."]},{"id":"Leverage_Chest_Press","n":"Wyciskanie na maszynie dźwigniowej","en":"Leverage Chest Press","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw obciążenie i wysokość siedziska tak, by uchwyty były na początku ruchu na wysokości dolnej lub środkowej części klatki.","Unieś klatkę i głowę, ściągnij łopatki. To pozycja startowa.","Wypchnij uchwyty do przodu, prostując łokcie.","Po krótkiej pauzie na górze wróć pod kontrolą, nie odkładając ciężaru na stosie aż do końca serii."],"tips":["Nie odrywaj pleców od oparcia i trzymaj łopatki ściągnięte.","Nie odkładaj ciężaru między powtórzeniami, utrzymuj napięcie."]},{"id":"Pushups","n":"Pompki klasyczne","en":"Pushups","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"body only","lvl":"beginner","u":"r","tags":["wristLoad"],"steps":["Przyjmij pozycję leżenia przodem, dłonie szeroko (około 90 cm), ramiona proste, tułów uniesiony.","Wdychając, opuść ciało, aż klatka prawie dotknie podłogi.","Na wydechu wypchnij ciało w górę, napinając klatkę.","Po krótkiej pauzie u góry powtarzaj ruch."],"tips":["Ciało trzymaj w jednej linii, bez zwisających bioder.","Nie wysuwaj głowy do przodu i nie skracaj zakresu ruchu."]},{"id":"Incline_Push-Up","n":"Pompki z rękami na podwyższeniu","en":"Incline Push-Up","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"body only","lvl":"beginner","u":"r","tags":["wristLoad"],"steps":["Stań przodem do ławki lub stabilnego podwyższenia. Oprzyj dłonie o krawędź, nieco szerzej niż barki.","Cofnij stopy tak, by ręce i ciało były proste, a ramiona prostopadłe do tułowia.","Zginając ręce, opuść klatkę do krawędzi podwyższenia.","Wypchnij ciało w górę do wyprostu rąk i powtarzaj."],"tips":["Utrzymuj sztywną linię od głowy do pięt.","Nie opuszczaj bioder i nie wyginaj lędźwi."]},{"id":"Push-Up_Wide","n":"Pompki szerokie","en":"Push-Up Wide","p":"hpush","m":["klatka"],"m2":["brzuch","barki","triceps"],"eq":"body only","lvl":"beginner","u":"r","tags":["shoulderStress","wristLoad"],"steps":["Przyjmij pozycję deski z szeroko rozstawionymi dłońmi, na palcach stóp. Ręce proste, ciało w jednej linii.","Wdychając, zegnij łokcie i opuść klatkę do podłogi.","Wydychając, wypchnij ciało w górę siłą mięśni piersiowych.","Po pauzie u góry powtórz ruch."],"tips":["Nie pozwól biodrom opadać.","Łokcie prowadź pod kontrolą i nie rozwieraj ich zbyt szeroko."]},{"id":"Decline_Push-Up","n":"Pompki ze stopami na podwyższeniu","en":"Decline Push-Up","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"body only","lvl":"beginner","u":"r","tags":["headDown","shoulderStress","wristLoad"],"steps":["Przyjmij pozycję leżenia przodem, dłonie szeroko (około 90 cm), ramiona proste. Stopy połóż na ławce lub skrzyni.","Wdychając, opuść ciało, aż klatka prawie dotknie podłogi.","Na wydechu wypchnij ciało w górę, napinając klatkę.","Po krótkiej pauzie powtarzaj ruch."],"tips":["Napnij brzuch i pośladki, by ciało było sztywne.","Nie zapadaj się w barkach i nie skracaj zakresu."]},{"id":"Dumbbell_Floor_Press","n":"Wyciskanie hantli leżąc na podłodze","en":"Dumbbell Floor Press","p":"hpush","m":["triceps"],"m2":["klatka","barki"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Połóż się na podłodze z hantlami w dłoniach, kolana mogą być ugięte. Zacznij z rękami wyprostowanymi nad sobą.","Opuszczaj ciężar, aż ramiona dotkną podłogi. Łokcie bliżej tułowia angażują triceps, szerzej klatkę.","Zatrzymaj się na dole i wypchnij hantle w górę, prostując łokcie."],"tips":["Na dole nie odkładaj ciężaru, tylko krótko się zatrzymaj.","Nie wyginaj lędźwi i trzymaj nadgarstki prosto."]},{"id":"Cable_Chest_Press","n":"Wyciskanie na wyciągu","en":"Cable Chest Press","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw odpowiedni ciężar i usiądź, chwytając uchwyty. Ramiona pod kątem około 45 stopni do tułowia, głowa i klatka uniesione, łokcie zgięte do 90 stopni.","Wyprostuj ręce, wypychając uchwyty przed siebie, z łopatkami ściągniętymi.","Zatrzymaj się w pełnym wyproście i wróć do pozycji startowej, utrzymując napięcie linek.","Możesz wykonywać ruch bez oparcia, na skosie lub naprzemiennie."],"tips":["Łopatki ściągnięte przez cały ruch.","Nie pozwalaj ciężarowi szarpać cię do tyłu."]},{"id":"Hammer_Grip_Incline_DB_Bench_Press","n":"Wyciskanie hantli chwytem neutralnym na skosie","en":"Hammer Grip Incline DB Bench Press","p":"hpush","m":["klatka"],"m2":["barki","triceps"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na ławce skośnej z hantlami na udach, dłonie zwrócone do siebie.","Pomagając sobie udami, unoś hantle po kolei na szerokość barków.","Zachowaj chwyt neutralny. Ramiona ustaw w linii barków, łokcie zgięte pod kątem 90 stopni.","Wdychając, powoli opuszczaj hantle po bokach.","Wydychając, wypchnij hantle w górę siłą klatki, zatrzymaj sekundę i opuszczaj.","Po serii odłóż hantle na uda, a potem na podłogę."],"tips":["Opuszczanie powinno trwać co najmniej dwa razy dłużej niż wyciskanie.","Przez cały ruch kontroluj hantle."]},{"id":"Parallel_Bar_Dip","n":"Pompki na poręczach","en":"Parallel Bar Dip","p":"hpush","m":["triceps"],"m2":["klatka","barki"],"eq":"machine","lvl":"beginner","u":"r","tags":["elbowStress","shoulderStress"],"steps":["Stań między poręczami, chwyć je i wskocz w podpór na prostych rękach.","Zginając łokcie, opuszczaj ciało, aż kąt w łokciach spadnie poniżej 90 stopni. Nie bujaj się, utrzymaj postawę.","Prostując łokcie, wypchnij się do pozycji wyjściowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie opuszczaj się zbyt głęboko, by nie przeciążać barków.","Unikaj bujania nogami i wzruszania barkami."]},{"id":"Dumbbell_Flyes","n":"Rozpiętki z hantlami","en":"Dumbbell Flyes","p":"chestiso","m":["klatka"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["shoulderStress"],"steps":["Połóż się na ławce płaskiej z hantlami na udach, dłonie zwrócone do siebie.","Pomagając sobie udami, unieś hantle nad klatkę na szerokość barków i zatrzymaj się tuż przed pełnym wyprostem.","Lekko zgięte łokcie, wdychając opuść ramiona szerokim łukiem, aż poczujesz rozciągnięcie klatki.","Wydychając, napnij klatkę i wróć tym samym łukiem do pozycji startowej.","Zatrzymaj się na sekundę i powtarzaj."],"tips":["Ruch odbywa się tylko w barkach, łokcie zachowują stały kąt.","Nie opuszczaj hantli zbyt nisko ani zbyt ciężkich."]},{"id":"Incline_Dumbbell_Flyes","n":"Rozpiętki na ławce skośnej","en":"Incline Dumbbell Flyes","p":"chestiso","m":["klatka"],"m2":["barki"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["shoulderStress"],"steps":["Weź hantle i połóż się na ławce skośnej ustawionej maksymalnie na 30 stopni.","Wyprostuj ramiona nad sobą z lekko zgiętymi łokciami.","Obróć nadgarstki dłońmi do siebie, małe palce obok siebie. To pozycja startowa.","Wdychając, powoli opuszczaj ramiona na boki, obracając nadgarstki, aż dłonie będą skierowane do siebie.","Wydychając, wróć do pozycji startowej odwrotnym ruchem.","Powtórz zaplanowaną liczbę razy."],"tips":["Ruch odbywa się w barkach i nadgarstkach, bez zginania łokci.","Nie ustawiaj ławki zbyt stromo."]},{"id":"Cable_Crossover","n":"Krzyżowanie linek wyciągu","en":"Cable Crossover","p":"chestiso","m":["klatka"],"m2":["barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw wyciągi wysoko nad głową, wybierz ciężar i chwyć uchwyty.","Zrób krok do przodu przed linię między wyciągami, ściągnij ręce przed siebie. Tułów lekko pochylony w przód.","Lekko zgiętymi łokciami, wdychając rozchyl ręce szerokim łukiem na boki, aż poczujesz rozciągnięcie klatki.","Wydychając, wróć do pozycji startowej tym samym łukiem.","Zatrzymaj się na sekundę i powtarzaj."],"tips":["Ruch tylko w barkach, ramiona i tułów pozostają nieruchome.","Nie prostuj łokci i nie pochylaj się coraz bardziej."]},{"id":"Low_Cable_Crossover","n":"Krzyżowanie linek z dolnych wyciągów","en":"Low Cable Crossover","p":"chestiso","m":["klatka"],"m2":["barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw wyciągi nisko, wybierz ciężar i chwyć uchwyty.","Zrób krok do przodu, napinając linki. Dłonie skierowane do przodu poniżej talii, ręce proste.","Lekko zgięte ramiona, unieś ręce w górę i do środka, aż dłonie spotkają się przed klatką, dłońmi do góry.","Po krótkiej pauzie wróć do pozycji startowej."],"tips":["Nie ciągnij rękami, tylko prowadź ruch klatką.","Tułów trzymaj stabilnie, bez bujania."]},{"id":"Butterfly","n":"Rozpiętki na maszynie (butterfly)","en":"Butterfly","p":"chestiso","m":["klatka"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na maszynie z plecami opartymi płasko o oparcie.","Chwyć uchwyty. Ramiona ustaw równolegle do podłogi, regulując maszynę. To pozycja startowa.","Na wydechu powoli zbliż uchwyty, ściskając klatkę pośrodku. Zatrzymaj sekundę.","Wdychając, powoli wróć do pozycji startowej do pełnego rozciągnięcia klatki.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie unoś barków do uszu.","Nie pozwalaj ciężarowi gwałtownie cofać ramion."]},{"id":"Straight-Arm_Dumbbell_Pullover","n":"Przenoszenie hantla za głowę (pullover)","en":"Straight-Arm Dumbbell Pullover","p":"chestiso","m":["klatka"],"m2":["najszersze grzbietu","barki","triceps"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":["overhead"],"steps":["Postaw hantel pionowo na ławce płaskiej.","Połóż się w poprzek ławki, tak by opierały się o nią tylko barki. Biodra niżej, nogi zgięte, stopy na podłodze, głowa poza ławką.","Chwyć hantel obiema dłońmi od spodu jednej z tarcz i trzymaj nad klatką na prostych rękach. Upewnij się, że hantel jest dobrze skręcony.","Wdychając, opuszczaj ciężar łukiem za głowę na prostych rękach, aż poczujesz rozciągnięcie klatki.","Wydychając, wróć tym samym łukiem do pozycji startowej i zatrzymaj sekundę.","Powtórz zaplanowaną liczbę razy."],"tips":["Używaj hantla z pewnie dokręconymi obciążeniami, by nie spadły.","Ręce trzymaj prosto i nie wyginaj nadmiernie lędźwi."]},{"id":"Barbell_Shoulder_Press","n":"Wyciskanie sztangi nad głowę siedząc","en":"Barbell Shoulder Press","p":"vpush","m":["barki"],"m2":["klatka","triceps"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","overhead"],"steps":["Usiądź na ławce z oparciem w stojaku. Ustaw sztangę tuż nad głową i chwyć ją nachwytem.","Podnieś sztangę nad głowę, prostując ręce, a potem trzymaj ją na wysokości barków, lekko przed głową.","Wdychając, powoli opuść sztangę do barków.","Wydychając, wypchnij sztangę do pozycji startowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie wyginaj mocno pleców i nie odrywaj ich od oparcia.","Prowadź sztangę pionowo, omijając twarz."]},{"id":"Standing_Military_Press","n":"Wyciskanie żołnierskie stojąc","en":"Standing Military Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial","overhead"],"steps":["Ustaw sztangę na stojaku na wysokości klatki, obciąż ją i chwyć nachwytem szerzej niż barki.","Lekko ugnij kolana, przenieś sztangę na obojczyki i klatkę. Cofnij się o krok i ustaw stopy na szerokość barków.","Wypchnij sztangę nad głowę, prostując ręce. Pozycja startowa: sztanga na wysokości barków, lekko przed głową.","Wdychając, powoli opuść sztangę do obojczyków.","Wydychając, wypchnij sztangę w górę. Powtórz zaplanowaną liczbę razy."],"tips":["Napnij brzuch i pośladki, nie wyginaj lędźwi.","Nie pomagaj sobie nogami, praca ma wykonywać górna część ciała."]},{"id":"Dumbbell_Shoulder_Press","n":"Wyciskanie hantli nad głowę","en":"Dumbbell Shoulder Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":["overhead"],"steps":["Usiądź na ławce z oparciem, trzymając hantle pionowo na udach.","Pomagając sobie udami, unoś hantle po kolei na wysokość barków.","Obróć nadgarstki dłońmi do przodu. To pozycja startowa.","Wydychając, wypchnij hantle w górę, aż się zetkną.","Po krótkiej pauzie wdychając powoli opuść hantle do pozycji startowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie wyginaj pleców, trzymaj je przy oparciu.","Opuszczaj hantle powoli, do wysokości uszu."]},{"id":"Seated_Dumbbell_Press","n":"Wyciskanie hantli siedząc","en":"Seated Dumbbell Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["overhead"],"steps":["Weź hantle i usiądź na ławce z oparciem, trzymając hantle pionowo na udach.","Unoś hantle po kolei na wysokość barków, pomagając sobie udami.","Obróć nadgarstki dłońmi do przodu. To pozycja startowa.","Wydychając, wypchnij hantle w górę, aż się zetkną.","Po sekundzie pauzy wdychając powoli opuść je do pozycji startowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie pomagaj sobie wyginaniem pleców.","Kontroluj hantle w fazie opuszczania."]},{"id":"Arnold_Dumbbell_Press","n":"Wyciskanie Arnolda","en":"Arnold Dumbbell Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":["overhead"],"steps":["Usiądź na ławce z oparciem, trzymając hantle przed sobą na wysokości górnej części klatki, dłońmi do siebie, łokcie zgięte. Pozycja jak przy szczycie uginania.","Unoś hantle, jednocześnie obracając dłonie do przodu.","Kontynuuj, aż ręce będą wyprostowane nad głową. Wydychaj podczas tej fazy.","Po sekundzie pauzy opuszczaj hantle, obracając dłonie z powrotem do siebie, wdychając.","Powtórz zaplanowaną liczbę razy."],"tips":["Obrót wykonuj płynnie, razem z wyciskaniem.","Nie bujaj tułowiem i trzymaj plecy na oparciu."]},{"id":"Machine_Shoulder_Military_Press","n":"Wyciskanie nad głowę na maszynie","en":"Machine Shoulder (Military) Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"machine","lvl":"beginner","u":"r","tags":["overhead"],"steps":["Usiądź na maszynie do wyciskania nad głowę i wybierz obciążenie.","Chwyć uchwyty po bokach, łokcie zgięte w linii tułowia. To pozycja startowa.","Wydychając, wypchnij uchwyty i wyprostuj ręce. Przytrzymaj napięcie na górze przez sekundę.","Wdychając, powoli opuść uchwyty do pozycji startowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Plecy trzymaj przy oparciu, bez wyginania lędźwi.","Nie blokuj łokci na górze i nie rzucaj ciężarem."]},{"id":"Standing_Palms-In_Dumbbell_Press","n":"Wyciskanie hantli stojąc chwytem neutralnym","en":"Standing Palms-In Dumbbell Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":["overhead"],"steps":["Stań na szerokość barków z hantlami w dłoniach, chwyt neutralny. Unieś hantle tak, by łokcie były zgięte do 90 stopni, a przedramiona prostopadłe do podłogi. To pozycja startowa.","Zachowując neutralny chwyt, powoli wypchnij hantle, aż ręce będą wyprostowane.","Wdychając, opuść ciężar, aż łokcie wrócą do kąta 90 stopni.","Powtórz zaplanowaną liczbę razy."],"tips":["Napnij brzuch i pośladki, by nie wyginać lędźwi.","Nie odchylaj się do tyłu, by pomóc sobie wypchnąć ciężar."]},{"id":"Landmine_Linear_Jammer","n":"Wyciskanie landmine","en":"Landmine Linear Jammer","p":"vpush","m":["barki"],"m2":["brzuch","łydki","klatka","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":[],"steps":["Włóż sztangę w uchwyt landmine lub zablokuj ją w rogu. Obciąż ją i załóż uchwyt.","Unieś sztangę z podłogi, przynosząc uchwyty do barków. To pozycja startowa.","W pozycji atletycznej zrób przysiad, odsuwając biodra w tył, ręce zgięte.","Dynamicznie wyprostuj biodra, kolana i kostki, jednocześnie prostując łokcie i wypychając sztangę.","Wróć do pozycji startowej."],"tips":["Ruch ma być wybuchowy, a energia płynąć z nóg i bioder.","Trzymaj proste plecy i napięty brzuch."]},{"id":"Two-Arm_Kettlebell_Military_Press","n":"Wyciskanie dwóch kettli nad głowę","en":"Two-Arm Kettlebell Military Press","p":"vpush","m":["barki"],"m2":["triceps"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":["overhead"],"steps":["Weź dwa kettlebelle na barki: prostując nogi i biodra, zamachnij je w stronę barków, obracając nadgarstki dłońmi do przodu.","Wypchnij kettlebelle w górę i na zewnątrz. Gdy miną głowę, przenieś ciężar tak, by znalazły się nad głową. Napnij plecy, pośladki i brzuch dla stabilności."],"tips":["Napnij brzuch i pośladki, żeby nie wyginać lędźwi.","Kettlebelle prowadź blisko ciała, bez przeciążania nadgarstków."]},{"id":"Side_Lateral_Raise","n":"Unoszenie hantli bokiem","en":"Side Lateral Raise","p":"shoulderiso","m":["barki"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Weź hantle i stań prosto, trzymając je przy bokach, dłońmi do siebie. To pozycja startowa.","Bez bujania tułowiem unieś hantle na boki, z lekko zgiętymi łokciami i dłońmi lekko pochylonymi do przodu, jakbyś wylewał wodę ze szklanki. Unoś do ramion równoległych do podłogi, wydychając, i zatrzymaj sekundę.","Wdychając, powoli opuść hantle do pozycji startowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Nie bujaj się i nie podnoś barków do uszu.","Unoś łokcie, nie dłonie, i nie przekraczaj wysokości barków."]},{"id":"Cable_Seated_Lateral_Raise","n":"Unoszenie ramion bokiem na wyciągu","en":"Cable Seated Lateral Raise","p":"shoulderiso","m":["barki"],"m2":["środek pleców","kaptury"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań między dwoma niskimi wyciągami, za sobą postaw ławkę wąskim bokiem do siebie. Ustaw ciężar na obu wyciągach.","Usiądź na brzegu ławki, stopy przed kolanami.","Pochyl się z płaskimi plecami i oprzyj tułów na udach.","Chwyć lewy uchwyt prawą ręką, a prawy lewą, linki pod kolanami. Ręce wyprostowane z lekko zgiętymi łokciami, dłonie zwrócone do siebie.","Wydychając, unieś ramiona na boki do wysokości barków i zatrzymaj sekundę.","Wdychając, powoli opuść ręce do pozycji startowej. Powtórz zaplanowaną liczbę razy."],"tips":["Zachowaj stały kąt w łokciach (10-30 stopni) i ramiona prostopadłe do tułowia.","Nie bujaj tułowiem i nie rzucaj ciężarem."]},{"id":"Front_Dumbbell_Raise","n":"Unoszenie hantli przodem","en":"Front Dumbbell Raise","p":"shoulderiso","m":["barki"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Weź hantle i stań prosto, trzymając je przed udami, dłońmi do ud. To pozycja startowa.","Bez bujania tułowiem unieś lewy hantel przed siebie z lekko zgiętym łokciem, dłoń cały czas skierowana w dół, do wysokości lekko powyżej poziomu. Wydychaj i zatrzymaj sekundę.","Powoli opuść hantel, jednocześnie unosząc prawy.","Kontynuuj naprzemiennie do zaplanowanej liczby powtórzeń na każdą rękę."],"tips":["Nie bujaj tułowiem i nie odchylaj się do tyłu.","Nie unoś hantli wyżej niż na wysokość oczu."]},{"id":"Reverse_Flyes","n":"Odwrotne rozpiętki z hantlami","en":"Reverse Flyes","p":"shoulderiso","m":["barki"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na ławce skośnej klatką i brzuchem do oparcia, z hantlami w dłoniach, chwyt neutralny.","Wyprostuj ręce przed sobą, prostopadle do ławki. Nogi nieruchome, nacisk na palce stóp. To pozycja startowa.","Z lekko zgiętymi łokciami wydychając, rozchyl hantle łukiem na boki.","Unoś ramiona, aż będą równoległe do podłogi, ściskając łopatki.","Poczuj napięcie i wdychając powoli opuść ciężar. Powtórz zaplanowaną liczbę razy."],"tips":["Ściągaj łopatki do siebie, żeby aktywować tylne aktony barków.","Nie bujaj się i nie używaj zbyt ciężkich hantli."]},{"id":"Reverse_Machine_Flyes","n":"Odwrotne rozpiętki na maszynie","en":"Reverse Machine Flyes","p":"shoulderiso","m":["barki"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw uchwyty maksymalnie z tyłu, wybierz ciężar i wysokość siedziska tak, by uchwyty były na wysokości barków. Chwyć je dłońmi do siebie.","Półkolistym ruchem rozciągnij ręce na boki i do tyłu, napinając tylne aktony barków.","Ręce trzymaj lekko zgięte, ruch wykonuj tylko w barkach.","Zatrzymaj się z tyłu i powoli wróć do pozycji startowej."],"tips":["Nie ciągnij łokciami zbyt daleko za plecy.","Nie unoś barków do uszu i nie szarp ciężarem."]},{"id":"Face_Pull","n":"Przyciąganie liny do twarzy (face pull)","en":"Face Pull","p":"shoulderiso","m":["barki"],"m2":["środek pleców"],"eq":"cable","lvl":"intermediate","u":"r","tags":[],"steps":["Stań przodem do wysokiego wyciągu z liną lub dwoma uchwytami.","Przyciągnij ciężar w stronę twarzy, rozdzielając dłonie. Ramiona utrzymuj równolegle do podłogi.","Powoli wróć do pozycji wyjściowej."],"tips":["Łokcie trzymaj wysoko, nie opuszczaj ich w dół.","Nie odchylaj tułowia, użyj lżejszego ciężaru."]},{"id":"Band_Pull_Apart","n":"Rozciąganie gumy przed sobą","en":"Band Pull Apart","p":"shoulderiso","m":["barki"],"m2":["środek pleców","kaptury"],"eq":"bands","lvl":"beginner","u":"r","tags":[],"steps":["Wyprostuj ręce przed sobą, trzymając gumę oburącz.","Rozciągnij gumę ruchem jak w odwrotnej rozpiętce, odwodząc dłonie na boki.","Ręce trzymaj wyprostowane, aż guma dotknie klatki, barki cofnięte.","Zatrzymaj się na chwilę i kontrolowanie wróć do pozycji startowej."],"tips":["Ściągaj łopatki, nie unoś barków.","Nie wyginaj lędźwi i nie szarp gumą."]},{"id":"External_Rotation_with_Band","n":"Rotacja zewnętrzna barku z gumą","en":"External Rotation with Band","p":"shoulderiso","m":["barki"],"m2":[],"eq":"bands","lvl":"beginner","u":"r","tags":[],"steps":["Zamocuj gumę na słupku na wysokości łokcia. Stań lewym bokiem do gumy w odległości kilku kroków.","Chwyć koniec gumy prawą ręką i przyciśnij łokieć do boku. Możesz trzymać łokciem ręcznik lub wałek.","Zegnij łokieć do 90 stopni, dłoń przed tułowiem. To pozycja startowa.","Obróć ramię na zewnątrz, nie odrywając łokcia od boku.","Wykonaj ruch tak daleko, jak możesz, zatrzymaj się i wróć."],"tips":["Łokieć nieruchomo przy tułowiu.","Ruch powolny i kontrolowany, bez zamachu."]},{"id":"Cable_Rear_Delt_Fly","n":"Odwrotne rozpiętki na wyciągu","en":"Cable Rear Delt Fly","p":"shoulderiso","m":["barki"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw wyciągi na odpowiedniej wysokości nad głową i wybierz ciężar.","Chwyć lewy uchwyt prawą ręką, a prawy lewą, krzyżując linki przed sobą. To pozycja startowa.","Odwodź ręce do tyłu i na zewnątrz, trzymając je wyprostowane.","Zatrzymaj się na końcu ruchu i wróć do pozycji startowej."],"tips":["Ruch wykonuj tylko w barkach, nie zginaj łokci.","Nie odchylaj tułowia i nie szarp ciężarem."]},{"id":"Lateral_Raise_-_With_Bands","n":"Unoszenie ramion bokiem z gumą","en":"Lateral Raise - With Bands","p":"shoulderiso","m":["barki"],"m2":[],"eq":"bands","lvl":"beginner","u":"r","tags":[],"steps":["Stań na gumie tak, by napięcie zaczynało się przy wyprostowanych rękach. Chwyć uchwyty nachwytem, trochę węziej niż barki, przy bokach ud. Plecy proste, łokcie lekko zgięte.","Wydychając, unieś uchwyty na boki bocznymi aktonami barków, do poziomu lekko powyżej równoległego. Lekko pochyl dłonie, jakbyś wylewał wodę, i zatrzymaj sekundę.","Wdychając, powoli opuść uchwyty do pozycji startowej.","Powtórz zaplanowaną liczbę razy."],"tips":["Tułów nieruchomo, bez bujania.","Nie unoś barków do uszu."]},{"id":"Dumbbell_Scaption","n":"Unoszenie hantli w płaszczyźnie łopatki","en":"Dumbbell Scaption","p":"shoulderiso","m":["barki"],"m2":["kaptury"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["To ćwiczenie korekcyjne wzmacnia mięśnie stabilizujące łopatkę. Weź lekkie hantle i trzymaj je opuszczone przy bokach, kciuki skierowane w górę.","Unoś ręce do przodu, około 30 stopni od linii środka ciała, z wyprostowanymi łokciami.","Unoś do równoległego z podłogą i wróć do pozycji startowej."],"tips":["Używaj lekkiego ciężaru i kontroluj ruch.","Nie unoś barków do uszu i nie bujaj tułowiem."]},{"id":"Seated_Bent-Over_Rear_Delt_Raise","n":"Unoszenie hantli w opadzie siedząc","en":"Seated Bent-Over Rear Delt Raise","p":"shoulderiso","m":["barki"],"m2":[],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Usiądź na końcu ławki, hantle trzymaj za łydkami.","Pochyl tułów prawie do ud, plecy proste, łokcie lekko ugięte.","Unieś hantle bokiem do wysokości barków, ściągając łopatki.","Zatrzymaj na sekundę i powoli opuść."],"tips":["Nie szarp tułowiem – ruch idzie z tylnych aktonów barków.","Użyj lekkiego ciężaru i pełnej kontroli."]},{"id":"Pullups","n":"Podciąganie nachwytem","en":"Pullups","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców"],"eq":"bar","lvl":"beginner","u":"r","tags":["overhead"],"steps":["Chwyć drążek nachwytem (dłonie do przodu). Chwyt szeroki: szerzej niż barki, średni: na szerokość barków, wąski: węziej.","Z wyprostowanymi rękami odchyl tułów do tyłu o około 30 stopni, wyginając lekko lędźwie i wypychając klatkę. To pozycja startowa.","Na wydechu podciągnij się, aż drążek dotknie górnej części klatki, ściągając barki i ramiona w dół i do tyłu. Napnij mięśnie pleców.","Po sekundzie pauzy, wdychając, powoli opuść tułów do pełnego wyprostu rąk i rozciągnięcia najszerszych grzbietu.","Powtórz zaplanowaną liczbę razy."],"tips":["Tułów pozostaje stabilny, pracują ręce, a przedramiona tylko trzymają drążek.","Nie bujaj się i nie podskakuj, kontroluj również opuszczanie."]},{"id":"Chin-Up","n":"Podciąganie podchwytem","en":"Chin-Up","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","przedramiona","środek pleców"],"eq":"bar","lvl":"beginner","u":"r","tags":["elbowStress","overhead"],"steps":["Chwyć drążek podchwytem (dłonie do siebie), węziej niż barki.","Z wyprostowanymi rękami utrzymuj tułów jak najprostszy, wyginając lekko lędźwie i wypychając klatkę. To pozycja startowa.","Na wydechu podciągnij się, aż głowa będzie na wysokości drążka, używając bicepsów i trzymając łokcie blisko ciała.","Po sekundzie ściśnięcia bicepsów powoli opuść tułów do pełnego wyprostu rąk, wdychając.","Powtórz zaplanowaną liczbę razy."],"tips":["Prosty tułów maksymalnie angażuje biceps i ogranicza pracę pleców.","Nie bujaj się i nie ciągnij przedramionami."]},{"id":"Band_Assisted_Pull-Up","n":"Podciąganie z gumą","en":"Band Assisted Pull-Up","p":"vpull","m":["najszersze grzbietu"],"m2":["brzuch","przedramiona","środek pleców"],"eq":"bar","lvl":"beginner","u":"r","tags":[],"steps":["Przełóż gumę przez środek drążka. Możesz dobrać gumę o różnym stopniu wsparcia.","Pociągnij koniec gumy w dół i włóż w pętlę zgięte kolano, tak by nie wypadło. Chwyć drążek średnim lub szerokim chwytem. To pozycja startowa.","Podciągnij się, napinając najszersze grzbietu i zginając łokcie, prowadząc łokcie do boków. Spróbuj przenieść brodę nad drążek, bez bujania i szarpania.","Po krótkiej pauzie wróć do pozycji startowej."],"tips":["Nie bujaj się i nie odbijaj od gumy.","Ruch kontrolowany, także w dół."]},{"id":"Wide-Grip_Lat_Pulldown","n":"Ściąganie drążka szerokim chwytem","en":"Wide-Grip Lat Pulldown","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców","barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź przy wyciągu górnym z szerokim drążkiem. Ustaw wałki na kolana odpowiednio do wzrostu, by ciało nie unosiło się.","Chwyć drążek nachwytem. Szeroki chwyt: szerzej niż barki, średni: na szerokość barków, wąski: węziej.","Z wyprostowanymi rękami odchyl tułów do tyłu o około 30 stopni, wyginając lekko lędźwie i wypychając klatkę.","Na wydechu przyciągnij drążek do górnej części klatki, ściągając barki i ramiona w dół i do tyłu, napinając plecy.","Po sekundzie ściągnięcia łopatek powoli unieś drążek do pełnego wyprostu rąk, wdychając. Powtórz zaplanowaną liczbę razy."],"tips":["Tułów stabilnie, pracują ręce; przedramiona tylko trzymają drążek.","Nie szarp ciężarem i nie odchylaj się zbyt mocno."]},{"id":"Close-Grip_Front_Lat_Pulldown","n":"Ściąganie drążka wąskim chwytem","en":"Close-Grip Front Lat Pulldown","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców","barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź przy wyciągu górnym i dopasuj wałki tak, aby unieruchomiły uda.","Chwyć drążek chwytem nachwytem węższym niż barki.","Odchyl tułów lekko do tyłu (ok. 30°), wypnij klatkę i utrzymaj naturalne wygięcie dolnego odcinka pleców.","Wydychając powietrze, ściągnij drążek do górnej części klatki, prowadząc łokcie w dół i do tyłu.","Zatrzymaj ruch na sekundę, ściśnij łopatki, po czym powoli wróć do pełnego wyprostu ramion."],"tips":["Nie bujaj tułowiem i nie szarp ciężaru – pracują plecy, nie pęd.","Nie ciągnij przedramionami; skup się na ruchu łokci w dół."]},{"id":"V-Bar_Pulldown","n":"Ściąganie uchwytu V do klatki","en":"V-Bar Pulldown","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców","barki"],"eq":"cable","lvl":"intermediate","u":"r","tags":[],"steps":["Usiądź przy wyciągu górnym z zamontowanym uchwytem V i zablokuj uda pod wałkami.","Chwyć uchwyt neutralnym chwytem, wypnij klatkę i odchyl tułów lekko do tyłu.","Wydychając powietrze, ściągnij uchwyt do górnej części klatki, ciągnąc łokcie w dół i do tyłu.","Ściśnij łopatki i zatrzymaj ruch na chwilę.","Powoli wróć do pozycji wyjściowej, kontrolując ciężar."],"tips":["Nie odchylaj się zbyt mocno – tułów ma pozostać stabilny.","Nie podciągaj barków do uszu; trzymaj łopatki w dół."]},{"id":"Underhand_Cable_Pulldowns","n":"Ściąganie drążka podchwytem","en":"Underhand Cable Pulldowns","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców","barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź przy wyciągu górnym i zablokuj uda pod wałkami.","Chwyć drążek podchwytem na szerokość barków.","Odchyl tułów lekko do tyłu i wypnij klatkę.","Ściągnij drążek do górnej części klatki, trzymając łokcie blisko ciała.","Zatrzymaj ruch w szczycie, po czym powoli wyprostuj ramiona."],"tips":["Nie bujaj tułowiem, aby pomóc sobie ciężarem.","Nie wyprostowuj ramion gwałtownie – kontroluj fazę negatywną."]},{"id":"One_Arm_Lat_Pulldown","n":"Ściąganie jednorącz na wyciągu","en":"One Arm Lat Pulldown","p":"vpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź bokiem lub przodem do wyciągu górnego z uchwytem pojedynczym i zablokuj uda.","Chwyć uchwyt jedną ręką, wolną rękę oprzyj na udzie lub maszynie.","Odchyl tułów lekko do tyłu i wypnij klatkę.","Ściągnij uchwyt w dół do boku klatki, prowadząc łokieć do tyłu i ściskając łopatkę.","Powoli wróć do pozycji wyjściowej z pełnym rozciągnięciem najszerszego grzbietu."],"tips":["Nie skręcaj tułowia w trakcie ruchu.","Nie ciągnij bicepsem – inicjuj ruch ściągnięciem łopatki."]},{"id":"Straight-Arm_Pulldown","n":"Ściąganie drążka prostymi rękami","en":"Straight-Arm Pulldown","p":"vpull","m":["najszersze grzbietu"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań przed wyciągiem górnym z krótkim drążkiem i chwyć go nachwytem na szerokość barków.","Pochyl tułów lekko do przodu, ugnij lekko kolana i lekko ugnij łokcie.","Wydychając powietrze, ściągnij drążek łukiem w dół do ud, utrzymując ramiona prawie proste.","Ściśnij mięśnie najszersze grzbietu i zatrzymaj ruch na chwilę.","Powoli wróć do pozycji wyjściowej."],"tips":["Nie zginaj łokci – to ma być ruch w stawie barkowym.","Nie bujaj tułowiem i nie zaokrąglaj pleców."]},{"id":"Scapular_Pull-Up","n":"Podciąganie łopatkowe","en":"Scapular Pull-Up","p":"vpull","m":["kaptury"],"m2":["najszersze grzbietu","środek pleców"],"eq":"bar","lvl":"beginner","u":"r","tags":[],"steps":["Chwyć drążek nachwytem nieco szerzej niż barki i zawiśnij z wyprostowanymi ramionami.","Rozluźnij barki, aby łopatki uniosły się ku górze.","Nie zginając łokci, opuść i ściągnij łopatki w dół, unosząc ciało o kilka centymetrów.","Zatrzymaj ruch na chwilę, po czym kontrolowanie wróć do zwisu."],"tips":["Nie zginaj łokci – ruch wykonują wyłącznie łopatki.","Nie bujaj się; pracuj powoli i pod kontrolą."]},{"id":"Bent_Over_Barbell_Row","n":"Wiosłowanie sztangą w opadzie","en":"Bent Over Barbell Row","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu","barki"],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial"],"steps":["Chwyć sztangę nachwytem nieco szerzej niż barki i unieś ją, prostując biodra.","Pochyl tułów do przodu (ok. 45° lub bliżej poziomu), ugnij lekko kolana i zachowaj proste plecy.","Przyciągnij sztangę do dolnej części brzucha, prowadząc łokcie do tyłu i ściskając łopatki.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść sztangę do pełnego wyprostu ramion."],"tips":["Nie zaokrąglaj pleców i nie unoś tułowia podczas ruchu.","Nie szarp ciężaru – utrzymaj stałą pozycję tułowia."]},{"id":"One-Arm_Dumbbell_Row","n":"Wiosłowanie hantlem jednorącz","en":"One-Arm Dumbbell Row","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu","barki"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Oprzyj kolano i rękę jednej strony o ławkę, drugą ręką chwyć hantel.","Utrzymaj proste plecy, równoległe do podłoża.","Przyciągnij hantel do boku tułowia, prowadząc łokieć blisko ciała i ściskając łopatkę.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść hantel do pełnego wyprostu ramienia, po czym zmień stronę."],"tips":["Nie skręcaj tułowia, aby unieść większy ciężar.","Nie ciągnij hantla bicepsem – prowadź ruch łokciem."]},{"id":"Seated_Cable_Rows","n":"Przyciąganie linki siedząc","en":"Seated Cable Rows","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu","barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź przy wyciągu dolnym, oprzyj stopy o podpórki i lekko ugnij kolana.","Chwyć uchwyt, wyprostuj plecy i wypnij klatkę.","Przyciągnij uchwyt do brzucha, prowadząc łokcie blisko ciała i ściskając łopatki.","Zatrzymaj ruch na sekundę w pełnym skurczu.","Powoli wyprostuj ramiona, pozwalając łopatkom się rozsunąć, bez zaokrąglania pleców."],"tips":["Nie bujaj tułowiem w przód i w tył.","Nie unoś barków do uszu podczas przyciągania."]},{"id":"Bent_Over_Two-Dumbbell_Row","n":"Wiosłowanie dwoma hantlami w opadzie","en":"Bent Over Two-Dumbbell Row","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu","barki"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Chwyć dwa hantle neutralnym lub nachwytem i pochyl tułów do przodu z prostymi plecami.","Ugnij lekko kolana, ramiona opuść swobodnie w dół.","Przyciągnij oba hantle do boków tułowia, ściskając łopatki.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść hantle do pełnego wyprostu ramion."],"tips":["Nie zaokrąglaj pleców i nie unoś tułowia podczas serii.","Nie używaj pędu – ruch ma być płynny i kontrolowany."]},{"id":"Dumbbell_Incline_Row","n":"Wiosłowanie hantlami leżąc na skosie","en":"Dumbbell Incline Row","p":"hpull","m":["środek pleców"],"m2":["biceps","przedramiona","najszersze grzbietu","barki"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na brzuchu na ławce skośnej, klatką oparty o oparcie, z hantlami w dłoniach.","Pozwól ramionom swobodnie zwisać w dół.","Przyciągnij hantle w górę do boków tułowia, ściskając łopatki.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść hantle do pełnego wyprostu ramion."],"tips":["Nie odrywaj klatki od ławki.","Nie unoś barków – prowadź ruch łokciami do tyłu."]},{"id":"T-Bar_Row_with_Handle","n":"Wiosłowanie T-bar","en":"T-Bar Row with Handle","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu"],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial"],"steps":["Stań nad sztangą T-bar z uchwytem, ugnij kolana i pochyl tułów z prostymi plecami.","Chwyć uchwyt i unieś ciężar, utrzymując tułów w stałej pozycji.","Przyciągnij ciężar do klatki lub górnej części brzucha, ściskając łopatki.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść ciężar do pełnego wyprostu ramion."],"tips":["Nie zaokrąglaj pleców i nie bujaj tułowiem.","Nie ciągnij samymi ramionami – inicjuj ruch ściągnięciem łopatek."]},{"id":"Inverted_Row","n":"Podciąganie australijskie","en":"Inverted Row","p":"hpull","m":["środek pleców"],"m2":["najszersze grzbietu"],"eq":"bar","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw sztangę w stojaku na wysokości pasa i połóż się pod nią, chwytając ją nachwytem nieco szerzej niż barki.","Zwiś z wyprostowanymi ramionami, ciało utrzymaj w linii prostej, pięty oprzyj o podłoże.","Podciągnij klatkę do sztangi, ściskając łopatki.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść ciało do pełnego wyprostu ramion."],"tips":["Nie zwieszaj bioder – napnij pośladki i brzuch.","Nie wysuwaj głowy do przodu; patrz przed siebie."]},{"id":"Leverage_Iso_Row","n":"Wiosłowanie na maszynie dźwigniowej","en":"Leverage Iso Row","p":"hpull","m":["najszersze grzbietu"],"m2":["biceps","środek pleców"],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na maszynie, oprzyj klatkę o podpórkę i ustaw stopy stabilnie.","Chwyć uchwyty i wyprostuj ramiona, wypinając klatkę.","Przyciągnij uchwyty do siebie, prowadząc łokcie do tyłu i ściskając łopatki.","Zatrzymaj ruch na chwilę w pełnym skurczu.","Powoli wróć do pozycji wyjściowej, kontrolując ciężar."],"tips":["Nie odrywaj klatki od podpórki.","Nie unoś barków – trzymaj je z dala od uszu."]},{"id":"One-Arm_Kettlebell_Row","n":"Wiosłowanie kettlem jednorącz","en":"One-Arm Kettlebell Row","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":[],"steps":["Ustaw się w pochyleniu, jedną ręką oprzyj się o ławkę lub udo, drugą chwyć kettlebell.","Utrzymaj proste plecy i stabilny tułów.","Przyciągnij kettlebell do boku tułowia, prowadząc łokieć blisko ciała i ściskając łopatkę.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść ciężar do pełnego wyprostu ramienia, po czym zmień stronę."],"tips":["Nie skręcaj tułowia, aby pomóc sobie ruchem.","Nie zaokrąglaj pleców."]},{"id":"Reverse_Grip_Bent-Over_Rows","n":"Wiosłowanie sztangą podchwytem","en":"Reverse Grip Bent-Over Rows","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu","barki"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial"],"steps":["Chwyć sztangę podchwytem na szerokość barków i unieś ją, prostując biodra.","Pochyl tułów do przodu (ok. 45°) z prostymi plecami i lekko ugiętymi kolanami.","Przyciągnij sztangę do dolnej części brzucha, trzymając łokcie blisko ciała.","Ściśnij łopatki i zatrzymaj ruch na chwilę.","Powoli opuść sztangę do pełnego wyprostu ramion."],"tips":["Nie zaokrąglaj pleców ani nie unoś tułowia.","Nie szarp ciężaru – bicepsy nie powinny przejmować pracy."]},{"id":"Suspended_Row","n":"Wiosłowanie na taśmach TRX","en":"Suspended Row","p":"hpull","m":["środek pleców"],"m2":["biceps","najszersze grzbietu"],"eq":"other","lvl":"beginner","u":"r","tags":[],"steps":["Chwyć uchwyty taśm TRX i odchyl się do tyłu z wyprostowanymi ramionami, ciało w jednej linii.","Ustaw stopy tak, aby uzyskać odpowiedni poziom trudności – im bardziej poziomo, tym ciężej.","Przyciągnij klatkę do uchwytów, ściskając łopatki i prowadząc łokcie do tyłu.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść ciało do pełnego wyprostu ramion."],"tips":["Nie zwieszaj bioder – napnij brzuch i pośladki.","Nie unoś barków do uszu."]},{"id":"Barbell_Shrug","n":"Szrugsy ze sztangą","en":"Barbell Shrug","p":"traps","m":["kaptury"],"m2":[],"eq":"barbell","lvl":"beginner","u":"r","tags":["axial","neckLoad"],"steps":["Stań prosto, trzymając sztangę nachwytem na szerokość barków, ramiona wyprostowane.","Unieś barki jak najwyżej, jakbyś chciał dotknąć nimi uszu.","Zatrzymaj ruch na sekundę w górze i ściśnij mięśnie czworoboczne.","Powoli opuść barki do pozycji wyjściowej."],"tips":["Nie zginaj łokci i nie wykonuj kółek barkami.","Nie wysuwaj głowy do przodu."]},{"id":"Dumbbell_Shrug","n":"Szrugsy z hantlami","en":"Dumbbell Shrug","p":"traps","m":["kaptury"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["neckLoad"],"steps":["Stań prosto z hantlami w dłoniach, ramiona opuszczone wzdłuż ciała.","Unieś barki jak najwyżej, nie zginając łokci.","Zatrzymaj ruch na sekundę w górze.","Powoli opuść barki do pozycji wyjściowej."],"tips":["Nie zginaj łokci – pracują tylko barki.","Unikaj bujania i kręcenia barkami."]},{"id":"Barbell_Curl","n":"Uginanie ramion ze sztangą","en":"Barbell Curl","p":"biceps","m":["biceps"],"m2":["przedramiona"],"eq":"barbell","lvl":"beginner","u":"r","tags":["elbowStress","wristLoad"],"steps":["Stań prosto, trzymając sztangę podchwytem na szerokość barków, łokcie przy tułowiu.","Wydychając powietrze, ugnij ramiona, unosząc sztangę do wysokości barków.","Ściśnij bicepsy i zatrzymaj ruch na chwilę.","Powoli opuść sztangę do pełnego wyprostu ramion."],"tips":["Nie bujaj tułowiem ani nie odchylaj się do tyłu.","Nie odsuwaj łokci od ciała."]},{"id":"Dumbbell_Bicep_Curl","n":"Uginanie ramion z hantlami","en":"Dumbbell Bicep Curl","p":"biceps","m":["biceps"],"m2":["przedramiona"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Stań prosto z hantlami w dłoniach, dłonie skierowane do przodu, łokcie przy tułowiu.","Wydychając powietrze, ugnij ramiona i unieś hantle do wysokości barków.","Ściśnij bicepsy i zatrzymaj ruch na chwilę.","Powoli opuść hantle do pełnego wyprostu ramion."],"tips":["Nie bujaj tułowiem i nie używaj pędu.","Utrzymuj łokcie nieruchomo przy ciele."]},{"id":"Dumbbell_Alternate_Bicep_Curl","n":"Uginanie ramion naprzemiennie","en":"Dumbbell Alternate Bicep Curl","p":"biceps","m":["biceps"],"m2":["przedramiona"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Stań prosto z hantlami w dłoniach, łokcie przy tułowiu.","Ugnij jedno ramię, unosząc hantel do barku i obracając nadgarstek na zewnątrz.","Ściśnij biceps w górze i zatrzymaj ruch na chwilę.","Powoli opuść hantel i powtórz ruch drugą ręką, wykonując serie naprzemiennie."],"tips":["Nie bujaj tułowiem.","Nie odsuwaj łokcia od ciała."]},{"id":"Hammer_Curls","n":"Uginanie młotkowe","en":"Hammer Curls","p":"biceps","m":["biceps"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Stań prosto z hantlami w dłoniach, dłonie zwrócone do siebie (chwyt młotkowy).","Utrzymując łokcie przy tułowiu, ugnij ramiona i unieś hantle do wysokości barków.","Zatrzymaj ruch na chwilę w górze.","Powoli opuść hantle do pełnego wyprostu ramion."],"tips":["Nie obracaj nadgarstków – chwyt neutralny przez cały ruch.","Nie bujaj tułowiem i nie odchylaj się do tyłu."]},{"id":"Incline_Dumbbell_Curl","n":"Uginanie ramion na ławce skośnej","en":"Incline Dumbbell Curl","p":"biceps","m":["biceps"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na ławce skośnej (ok. 45–60°), oprzyj plecy i trzymaj hantle z ramionami swobodnie zwisającymi.","Wydychając powietrze, ugnij ramiona, unosząc hantle bez ruszania łokciami do przodu.","Ściśnij bicepsy w górze i zatrzymaj ruch na chwilę.","Powoli opuść hantle do pełnego rozciągnięcia bicepsów."],"tips":["Nie odrywaj pleców od ławki i nie wysuwaj barków do przodu.","Unikaj bujania – kontroluj fazę opuszczania."]},{"id":"Preacher_Curl","n":"Uginanie na modlitewniku","en":"Preacher Curl","p":"biceps","m":["biceps"],"m2":[],"eq":"barbell","lvl":"beginner","u":"r","tags":["elbowStress","wristLoad"],"steps":["Usiądź przy modlitewniku, oprzyj tricepsy na podpórce i chwyć sztangę lub hantle podchwytem.","Wydychając powietrze, ugnij ramiona i unieś ciężar w kierunku barków.","Ściśnij bicepsy i zatrzymaj ruch na chwilę.","Powoli opuść ciężar prawie do pełnego wyprostu ramion."],"tips":["Nie odrywaj ramion od podpórki ani nie szarp na dole.","Nie prostuj łokci gwałtownie, aby chronić ścięgna."]},{"id":"Concentration_Curls","n":"Uginanie w koncentracji","en":"Concentration Curls","p":"biceps","m":["biceps"],"m2":["przedramiona"],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Usiądź na ławce, rozstaw szeroko nogi i chwyć hantel jedną ręką, opierając łokieć o wewnętrzną stronę uda.","Wydychając powietrze, ugnij ramię, unosząc hantel w kierunku barku.","Ściśnij biceps w górze i zatrzymaj ruch na chwilę.","Powoli opuść hantel do pełnego wyprostu, po czym zmień rękę."],"tips":["Nie bujaj tułowiem i nie pomagaj sobie ramieniem.","Utrzymuj łokieć w stałym kontakcie z udem."]},{"id":"Cable_Hammer_Curls_-_Rope_Attachment","n":"Uginanie młotkowe z liną na wyciągu","en":"Cable Hammer Curls - Rope Attachment","p":"biceps","m":["biceps"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań przed dolnym wyciągiem z liną i chwyć ją chwytem młotkowym, łokcie przy tułowiu.","Wydychając powietrze, ugnij ramiona i unieś linę w kierunku barków.","Ściśnij bicepsy i mięśnie ramienne, zatrzymując ruch na chwilę.","Powoli opuść linę do pełnego wyprostu ramion."],"tips":["Nie odsuwaj łokci od ciała.","Nie odchylaj się do tyłu – tułów pozostaje nieruchomy."]},{"id":"Standing_Biceps_Cable_Curl","n":"Uginanie ramion na dolnym wyciągu","en":"Standing Biceps Cable Curl","p":"biceps","m":["biceps"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań przed dolnym wyciągiem z prostym drążkiem, chwyć go podchwytem na szerokość barków.","Łokcie trzymaj przy tułowiu, ugnij ramiona i unieś drążek do wysokości barków.","Ściśnij bicepsy i zatrzymaj ruch na chwilę.","Powoli opuść drążek do pełnego wyprostu ramion."],"tips":["Nie bujaj tułowiem i nie odchylaj się do tyłu.","Nie przesuwaj łokci do przodu."]},{"id":"Machine_Bicep_Curl","n":"Uginanie ramion na maszynie","en":"Machine Bicep Curl","p":"biceps","m":["biceps"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw wysokość siedziska tak, aby ramiona leżały na podpórce, i chwyć uchwyty podchwytem.","Wydychając powietrze, ugnij ramiona i unieś uchwyty w kierunku barków.","Ściśnij bicepsy i zatrzymaj ruch na chwilę.","Powoli wróć do pozycji wyjściowej, kontrolując ciężar."],"tips":["Nie odrywaj ramion od podpórki.","Nie opuszczaj ciężaru gwałtownie – kontroluj fazę negatywną."]},{"id":"Zottman_Curl","n":"Uginanie Zottmana","en":"Zottman Curl","p":"biceps","m":["biceps"],"m2":["przedramiona"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":[],"steps":["Stań prosto z hantlami w dłoniach, dłonie skierowane do przodu (podchwyt), łokcie przy tułowiu.","Ugnij ramiona i unieś hantle do wysokości barków.","W szczycie ruchu obróć nadgarstki tak, aby dłonie były skierowane w dół (nachwyt).","Powoli opuść hantle w nachwycie, na dole znów obróć nadgarstki do podchwytu i powtórz."],"tips":["Nie bujaj tułowiem i nie odsuwaj łokci od ciała.","Wykonuj obrót nadgarstków wolno i płynnie."]},{"id":"Triceps_Pushdown","n":"Prostowanie ramion na wyciągu","en":"Triceps Pushdown","p":"triceps","m":["triceps"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań przed górnym wyciągiem z prostym lub łamanym drążkiem, chwyć go nachwytem, łokcie przy tułowiu.","Pochyl się lekko do przodu i ugnij łokcie, tak aby przedramiona były skierowane w górę.","Wydychając powietrze, wyprostuj ramiona, naciskając drążek w dół do ud.","Ściśnij tricepsy i zatrzymaj ruch na chwilę.","Powoli wróć do pozycji wyjściowej."],"tips":["Nie odsuwaj łokci od ciała ani nie unoś barków.","Nie bujaj tułowiem, aby pomóc sobie ciężarem."]},{"id":"Triceps_Pushdown_-_Rope_Attachment","n":"Prostowanie ramion z liną na wyciągu","en":"Triceps Pushdown - Rope Attachment","p":"triceps","m":["triceps"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Stań przed górnym wyciągiem z liną, chwyć ją neutralnym chwytem, łokcie przy tułowiu.","Pochyl się lekko do przodu i ugnij łokcie do kąta ok. 90°.","Wydychając powietrze, wyprostuj ramiona, naciskając linę w dół i rozchylając jej końce na boki.","Ściśnij tricepsy w dolnej pozycji.","Powoli wróć do pozycji wyjściowej."],"tips":["Nie odsuwaj łokci od tułowia.","Nie pomagaj sobie ruchem bioder i barków."]},{"id":"Bench_Dips","n":"Pompki w podporze tyłem na ławce","en":"Bench Dips","p":"triceps","m":["triceps"],"m2":["klatka","barki"],"eq":"body only","lvl":"beginner","u":"r","tags":["shoulderStress","wristLoad"],"steps":["Usiądź na brzegu ławki i oprzyj dłonie obok bioder, a nogi wyprostuj lub ugnij.","Zsuń biodra z ławki i wyprostuj ramiona, opierając ciężar ciała na dłoniach.","Wdychając powietrze, ugnij łokcie i opuść ciało w dół, aż ramiona znajdą się w kącie ok. 90°.","Wydychając powietrze, wyprostuj ramiona, unosząc ciało do pozycji wyjściowej."],"tips":["Trzymaj plecy blisko ławki i łokcie skierowane do tyłu.","Nie opuszczaj się zbyt głęboko – chroń barki."]},{"id":"Dips_-_Triceps_Version","n":"Pompki na poręczach – wersja na triceps","en":"Dips - Triceps Version","p":"triceps","m":["triceps"],"m2":["klatka","barki"],"eq":"machine","lvl":"beginner","u":"r","tags":["elbowStress","shoulderStress"],"steps":["Chwyć poręcze i unieś ciało na wyprostowanych ramionach, tułów lekko pochylony do przodu lub pionowo.","Wdychając powietrze, opuść ciało, trzymając łokcie blisko tułowia, do kąta ok. 90° w łokciach.","Wydychając powietrze, wyprostuj ramiona, unosząc ciało do pozycji wyjściowej.","Ściśnij tricepsy w górze."],"tips":["Utrzymuj tułów pionowo i łokcie blisko ciała, aby akcentować triceps.","Nie opuszczaj się zbyt głęboko i nie bujaj nogami."]},{"id":"Lying_Dumbbell_Tricep_Extension","n":"Wyprosty ramion z hantlami leżąc","en":"Lying Dumbbell Tricep Extension","p":"triceps","m":["triceps"],"m2":["klatka","barki"],"eq":"dumbbell","lvl":"intermediate","u":"r","tags":["elbowStress"],"steps":["Połóż się na ławce płaskiej z hantlami w dłoniach, ramiona wyprostowane nad klatką, dłonie zwrócone do siebie.","Utrzymując ramiona nieruchomo, ugnij łokcie i opuść hantle w kierunku boków głowy.","Zatrzymaj ruch na chwilę na dole.","Wydychając powietrze, wyprostuj ramiona, unosząc hantle do pozycji wyjściowej."],"tips":["Nie odsuwaj łokci na boki – trzymaj je skierowane do góry.","Opuszczaj ciężar powoli i z kontrolą."]},{"id":"Standing_Dumbbell_Triceps_Extension","n":"Wyprost hantla zza głowy stojąc","en":"Standing Dumbbell Triceps Extension","p":"triceps","m":["triceps"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":["elbowStress","overhead"],"steps":["Stań prosto, chwyć jeden hantel oburącz i unieś go nad głowę na wyprostowanych ramionach.","Utrzymując ramiona blisko głowy, ugnij łokcie i opuść hantel za głowę.","Zatrzymaj ruch na chwilę w dolnym położeniu.","Wydychając powietrze, wyprostuj ramiona, unosząc hantel do pozycji wyjściowej."],"tips":["Nie rozchylaj łokci na boki i nie wyginaj pleców.","Napnij brzuch, aby ustabilizować tułów."]},{"id":"Triceps_Overhead_Extension_with_Rope","n":"Wyprosty zza głowy z liną","en":"Triceps Overhead Extension with Rope","p":"triceps","m":["triceps"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":["elbowStress","overhead"],"steps":["Ustaw się tyłem do górnego wyciągu z liną, chwyć ją oburącz i unieś ramiona nad głowę, łokcie ugięte.","Wykonaj krok do przodu i ustabilizuj tułów, łokcie trzymaj blisko głowy.","Wydychając powietrze, wyprostuj ramiona do przodu i w górę, rozchylając końce liny.","Ściśnij tricepsy i zatrzymaj ruch na chwilę.","Powoli wróć do pozycji wyjściowej."],"tips":["Nie ruszaj łokciami – pracują tylko przedramiona.","Nie wyginaj dolnego odcinka pleców."]},{"id":"Tricep_Dumbbell_Kickback","n":"Prostowanie ramienia w opadzie (kickback)","en":"Tricep Dumbbell Kickback","p":"triceps","m":["triceps"],"m2":[],"eq":"dumbbell","lvl":"beginner","u":"r","tags":[],"steps":["Pochyl tułów, oprzyj jedną rękę i kolano o ławkę, w drugiej ręce trzymaj hantel z łokciem przy tułowiu.","Ustaw ramię równolegle do tułowia, a przedramię prostopadle do podłoża.","Wydychając powietrze, wyprostuj ramię do tyłu, unieruchamiając ramię.","Ściśnij triceps i zatrzymaj ruch na chwilę.","Powoli wróć do pozycji wyjściowej, po czym zmień stronę."],"tips":["Nie unoś i nie opuszczaj ramienia – rusza się tylko przedramię.","Nie bujaj tułowiem."]},{"id":"Push-Ups_-_Close_Triceps_Position","n":"Pompki diamentowe / wąskie","en":"Push-Ups - Close Triceps Position","p":"triceps","m":["triceps"],"m2":["klatka","barki"],"eq":"body only","lvl":"intermediate","u":"r","tags":["wristLoad"],"steps":["Przyjmij pozycję podporu przodem z dłońmi blisko siebie pod klatką, tworząc romb kciukami i palcami wskazującymi.","Utrzymaj ciało w linii prostej od głowy do pięt.","Wdychając powietrze, ugnij łokcie i opuść klatkę do dłoni, trzymając łokcie blisko tułowia.","Wydychając powietrze, wypchnij ciało w górę do pełnego wyprostu ramion."],"tips":["Nie opuszczaj bioder ani nie unoś pośladków.","Trzymaj łokcie blisko ciała, nie rozchylaj ich na boki."]},{"id":"Close-Grip_Barbell_Bench_Press","n":"Wyciskanie sztangi wąskim chwytem","en":"Close-Grip Barbell Bench Press","p":"triceps","m":["triceps"],"m2":["klatka","barki"],"eq":"barbell","lvl":"beginner","u":"r","tags":["elbowStress"],"steps":["Połóż się na ławce płaskiej i chwyć sztangę nachwytem na szerokość barków lub nieco węziej.","Zdejmij sztangę ze stojaka i ustaw ją nad dolną częścią klatki na wyprostowanych ramionach.","Wdychając powietrze, opuść sztangę do dolnej części klatki, trzymając łokcie blisko tułowia.","Wydychając powietrze, wyciśnij sztangę w górę, koncentrując się na pracy tricepsów."],"tips":["Nie chwytaj zbyt wąsko – obciąża to nadgarstki.","Nie rozchylaj łokci na boki i nie odbijaj sztangi od klatki."]},{"id":"Plank","n":"Deska (plank)","en":"Plank","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Przyjmij pozycję podporu na przedramionach, łokcie pod barkami, a nogi wyprostowane i oparte na palcach.","Napnij brzuch i pośladki, utrzymując ciało w linii prostej od głowy do pięt.","Patrz w podłoże, oddychaj równomiernie.","Utrzymaj pozycję przez zaplanowany czas."],"tips":["Nie opuszczaj bioder ani nie unoś pośladków.","Nie zadzieraj głowy i nie wstrzymuj oddechu."]},{"id":"Side_Bridge","n":"Deska bokiem","en":"Side Bridge","p":"core","m":["brzuch"],"m2":["barki"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Połóż się na boku, oprzyj się na przedramieniu z łokciem pod barkiem, a nogi ułóż jedna na drugiej.","Unieś biodra tak, aby ciało utworzyło prostą linię od głowy do stóp.","Napnij mięśnie brzucha i utrzymaj pozycję przez zaplanowany czas.","Opuść biodra, po czym zmień stronę."],"tips":["Nie opuszczaj bioder ani nie przechylaj tułowia do przodu lub tyłu.","Trzymaj bark nad łokciem, a szyję w przedłużeniu kręgosłupa."]},{"id":"Dead_Bug","n":"Martwy robak (dead bug)","en":"Dead Bug","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na plecach, wyprostuj ramiona w górę nad klatką, a nogi unieś z kolanami ugiętymi pod kątem 90°.","Dociśnij dolny odcinek pleców do podłoża i napnij brzuch.","Powoli opuść jedną rękę za głowę i przeciwną nogę w kierunku podłoża.","Wróć do pozycji wyjściowej i powtórz ruch drugą stroną."],"tips":["Nie odrywaj lędźwi od podłoża.","Wykonuj ruch powoli, oddychając równomiernie."]},{"id":"Pallof_Press","n":"Pallof press","en":"Pallof Press","p":"core","m":["brzuch"],"m2":["klatka","barki","triceps"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Ustaw się bokiem do wyciągu na wysokości klatki, chwyć uchwyt oburącz przy klatce i odsuń się na stabilną pozycję.","Rozstaw stopy na szerokość barków, lekko ugnij kolana i napnij brzuch.","Wydychając powietrze, wyprostuj ramiona przed sobą, nie pozwalając tułowiowi skręcić się w stronę wyciągu.","Zatrzymaj ruch na chwilę, po czym przyciągnij uchwyt z powrotem do klatki."],"tips":["Nie pozwól, aby wyciąg skręcił Twój tułów.","Utrzymuj biodra i barki w jednej linii."]},{"id":"Crunches","n":"Brzuszki","en":"Crunches","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":["neckLoad","spinalFlex"],"steps":["Połóż się na plecach, ugnij kolana, stopy oprzyj o podłoże, a dłonie przyłóż do skroni lub skrzyżuj na klatce.","Wydychając powietrze, unieś łopatki od podłoża, skracając odległość między klatką a miednicą.","Zatrzymaj ruch na chwilę i napnij brzuch.","Powoli opuść tułów do pozycji wyjściowej."],"tips":["Nie ciągnij głowy rękami za szyję.","Nie unoś całego tułowia – wystarczy oderwać łopatki."]},{"id":"Reverse_Crunch","n":"Odwrotne brzuszki","en":"Reverse Crunch","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na plecach, ramiona ułóż wzdłuż ciała, a nogi unieś z kolanami ugiętymi pod kątem 90°.","Wydychając powietrze, przyciągnij kolana w stronę klatki, unosząc miednicę od podłoża.","Zatrzymaj ruch na chwilę i napnij dolną część brzucha.","Powoli opuść miednicę do pozycji wyjściowej."],"tips":["Nie bujaj nogami – ruch inicjuje brzuch.","Nie odrywaj górnej części pleców od podłoża."]},{"id":"Cable_Crunch","n":"Spięcia brzucha na wyciągu klęcząc","en":"Cable Crunch","p":"core","m":["brzuch"],"m2":[],"eq":"cable","lvl":"beginner","u":"r","tags":["spinalFlex"],"steps":["Uklęknij przed górnym wyciągiem z liną, chwyć ją i przytrzymaj przy głowie lub na barkach.","Biodra trzymaj nieruchomo i napnij brzuch.","Wydychając powietrze, zegnij tułów w dół, zbliżając łokcie do ud.","Zatrzymaj ruch na chwilę, po czym powoli wróć do pozycji wyjściowej."],"tips":["Nie ciągnij ciężaru rękami ani nie poruszaj biodrami.","Zginaj tułów w kręgosłupie, nie w stawie biodrowym."]},{"id":"Russian_Twist","n":"Rosyjskie skręty","en":"Russian Twist","p":"core","m":["brzuch"],"m2":["dolny odc. pleców"],"eq":"body only","lvl":"intermediate","u":"r","tags":["spinalFlex"],"steps":["Usiądź na podłodze, ugnij kolana, odchyl tułów do tyłu i unieś stopy lekko nad podłoże, trzymając ciężar lub złączone dłonie przed sobą.","Utrzymaj proste plecy i napnięty brzuch.","Skręć tułów w jedną stronę, przenosząc ciężar obok biodra.","Wróć do środka i skręć tułów w drugą stronę."],"tips":["Obracaj tułów, a nie tylko ramiona.","Nie zaokrąglaj pleców i nie wstrzymuj oddechu."]},{"id":"Flat_Bench_Lying_Leg_Raise","n":"Unoszenie nóg leżąc na ławce","en":"Flat Bench Lying Leg Raise","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":["spinalFlex"],"steps":["Połóż się na plecach na ławce płaskiej, chwyć ławkę za głową lub połóż dłonie pod pośladkami, a nogi wyprostuj.","Wydychając powietrze, unieś proste nogi do kąta ok. 90° względem tułowia.","Zatrzymaj ruch na chwilę i napnij brzuch.","Powoli opuść nogi, nie dotykając nimi podłoża."],"tips":["Nie odrywaj lędźwi od ławki – dociśnij je do niej.","Opuszczaj nogi powoli, bez bujania."]},{"id":"Knee_Hip_Raise_On_Parallel_Bars","n":"Unoszenie kolan w podporze na poręczach","en":"Knee/Hip Raise On Parallel Bars","p":"core","m":["brzuch"],"m2":[],"eq":"machine","lvl":"beginner","u":"r","tags":[],"steps":["Wejdź w podpór na poręczach, ramiona wyprostowane, plecy oparte o podpórkę, nogi swobodnie zwisają.","Napnij brzuch i lekko odchyl barki w tył.","Wydychając powietrze, unieś ugięte kolana w kierunku klatki, zwijając miednicę.","Zatrzymaj ruch na chwilę, po czym powoli opuść nogi."],"tips":["Nie bujaj się – unoś kolana siłą mięśni brzucha.","Nie unoś barków do uszu."]},{"id":"Barbell_Ab_Rollout","n":"Rollout ze sztangą (kółko)","en":"Barbell Ab Rollout","p":"core","m":["brzuch"],"m2":["dolny odc. pleców","barki"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["spinalFlex"],"steps":["Przyjmij pozycję jak do pompki, ale chwyć sztangę olimpijską obciążoną 2–5 kg z każdej strony.","Utrzymując lekkie wygięcie pleców, unieś biodra i przetocz sztangę w stronę stóp, wydychając powietrze.","Zatrzymaj się na sekundę w pełnym skurczu.","Powoli przetocz sztangę z powrotem do pozycji wyjściowej, wdychając powietrze.","Powtórz zalecaną liczbę powtórzeń."],"tips":["Trzymaj brzuch napięty i nie zapadaj się w odcinku lędźwiowym.","Ramiona prowadź prostopadle do podłogi, inaczej zaangażujesz barki i plecy zamiast brzucha."]},{"id":"Standing_Cable_Wood_Chop","n":"Drwal na wyciągu","en":"Standing Cable Wood Chop","p":"core","m":["brzuch"],"m2":["barki"],"eq":"cable","lvl":"beginner","u":"r","tags":[],"steps":["Zamocuj zwykły uchwyt do wyciągu i ustaw linkę w najwyższej pozycji.","Stań bokiem do wyciągu, chwyć uchwyt jedną ręką i odsuń się na długość ręki, tak by linka była napięta.","Stopy rozstaw na szerokość barków i chwyć uchwyt obiema dłońmi, ramiona wyprostowane.","Jednym płynnym ruchem pociągnij uchwyt w dół i w poprzek ciała do przedniego kolana, skręcając tułów.","Obróć tylną stopę i ugnij kolana, aby uzyskać pełny zakres ruchu.","Powoli wróć do pozycji wyjściowej i po serii zmień stronę."],"tips":["Ramiona trzymaj prosto, a ruch wykonuj tułowiem, nie rękami.","Napnij brzuch i wracaj kontrolowanie, bez szarpania."]},{"id":"Bent-Knee_Hip_Raise","n":"Unoszenie bioder leżąc z ugiętymi nogami","en":"Bent-Knee Hip Raise","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się na plecach, ramiona wzdłuż tułowia.","Ugnij kolana pod kątem ok. 75° i unieś stopy ok. 5 cm nad podłogę.","Dolnymi partiami brzucha przyciągaj kolana do siebie, zachowując kąt w nogach.","Unieś biodra z podłogi, zwijając miednicę do tyłu, i wydychaj powietrze.","Na górze kolana są nad klatką piersiową; napnij brzuch na sekundę.","Powoli wróć do pozycji wyjściowej, wdychając powietrze."],"tips":["Wykonuj ruch powoli, bez bujania nogami.","Nie odpychaj się rękami od podłogi, pracuj dolnym brzuchem."]},{"id":"Ab_Crunch_Machine","n":"Spięcia brzucha na maszynie","en":"Ab Crunch Machine","p":"core","m":["brzuch"],"m2":[],"eq":"machine","lvl":"intermediate","u":"r","tags":["spinalFlex"],"steps":["Ustaw niewielki ciężar i usiądź na maszynie, stopy wsuń pod wałki, a dłońmi chwyć górne uchwyty.","Ugnij ramiona pod kątem 90° i oprzyj triceps na poduszkach.","Jednocześnie unieś nogi i zegnij górną część tułowia, wydychając powietrze.","Zatrzymaj się na sekundę w skurczu.","Powoli wróć do pozycji wyjściowej, wdychając powietrze."],"tips":["Pracuj brzuchem, a nogi i stopy zostaw rozluźnione.","Poruszaj się wolno i kontrolowanie, bez szarpnięć."]},{"id":"Air_Bike","n":"Rowerek leżąc","en":"Air Bike","p":"core","m":["brzuch"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":["spinalFlex"],"steps":["Połóż się na plecach, dolny odcinek pleców przyciśnij do podłogi, a dłonie przyłóż po bokach głowy.","Unieś barki do pozycji skrętu brzucha.","Ugnij kolana tak, by uda były prostopadłe do podłogi, a podudzia równoległe do niej.","Wykonuj ruch jak pedałowanie: wyprostuj prawą nogę, a lewe kolano przyciągnij i skręć tułów, by prawy łokieć zbliżyć do lewego kolana. Wydychaj powietrze.","Zmień stronę, wdychając powietrze i zbliżając lewy łokieć do prawego kolana.","Kontynuuj naprzemiennie przez zalecaną liczbę powtórzeń."],"tips":["Nie ciągnij głowy rękami i nie przeciążaj szyi.","Skręcaj tułów, a nie tylko łokcie, i trzymaj dolne plecy przy podłożu."]},{"id":"Superman","n":"Superman","en":"Superman","p":"core","m":["dolny odc. pleców"],"m2":["pośladki","dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Połóż się twarzą do podłogi na macie, ramiona wyprostowane przed sobą.","Jednocześnie unieś ramiona, nogi i klatkę piersiową nad podłogę, wydychając powietrze.","Utrzymaj napięcie przez 2 sekundy, jak lecący Superman.","Powoli opuść ramiona, nogi i klatkę do pozycji wyjściowej, wdychając powietrze.","Powtórz zalecaną liczbę powtórzeń."],"tips":["Napnij mięśnie dolnych pleców i pośladki.","Nie odchylaj nadmiernie głowy, patrz w podłogę."]},{"id":"Mountain_Climbers","n":"Wspinaczka górska (mountain climbers)","en":"Mountain Climbers","p":"core","m":["czworogłowe uda"],"m2":["klatka","dwugłowe uda","barki"],"eq":"body only","lvl":"beginner","u":"s","tags":["highIntensity","wristLoad"],"steps":["Przyjmij pozycję jak do pompki, opierając ciężar na dłoniach i palcach stóp.","Zegnij kolano i biodro, przyciągając jedną nogę tak, by kolano było mniej więcej pod biodrem.","Dynamicznie zamień nogi: wyprostuj zgiętą nogę i oprzyj ją na palcach, a drugą przyciągnij.","Powtarzaj naprzemiennie przez 20–30 sekund."],"tips":["Trzymaj biodra nisko, w jednej linii z tułowiem.","Napnij brzuch i nie unoś pośladków do góry."]},{"id":"Walking_Treadmill","n":"Marsz na bieżni","en":"Walking, Treadmill","p":"cardio","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"min","tags":[],"steps":["Wejdź na bieżnię i wybierz opcję z menu: tryb ręczny lub gotowy program.","Wprowadź wiek i wagę, jeśli chcesz oszacować spalone kalorie.","Ustaw nachylenie, aby zmienić intensywność treningu.","Maszeruj w umiarkowanym lub szybkim tempie, nie spacerowym.","Trzymaj prawidłową postawę i łap za poręcze tylko w razie potrzeby."],"tips":["Nie opieraj się ciężarem na poręczach, bo obniżasz intensywność.","Wyprostuj sylwetkę i patrz przed siebie."]},{"id":"Jogging_Treadmill","n":"Trucht na bieżni","en":"Jogging, Treadmill","p":"cardio","m":["czworogłowe uda"],"m2":["pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"min","tags":["impact","kneeStress"],"steps":["Wejdź na bieżnię i wybierz opcję z menu: tryb ręczny lub gotowy program.","Wprowadź wiek i wagę, jeśli chcesz oszacować spalone kalorie.","Ustaw nachylenie, aby zmienić intensywność treningu.","Truchtaj w równym, komfortowym tempie.","Trzymaj prawidłową postawę i łap za poręcze tylko przy schodzeniu lub kontroli tętna."],"tips":["Nie trzymaj się poręczy podczas biegu.","Lądowanie miękkie, tułów wyprostowany, wzrok przed siebie."]},{"id":"Elliptical_Trainer","n":"Orbitrek","en":"Elliptical Trainer","p":"cardio","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"intermediate","u":"min","tags":[],"steps":["Wejdź na orbitrek i wybierz opcję z menu: tryb ręczny lub program.","Wprowadź wiek i wagę, jeśli chcesz oszacować spalone kalorie.","Ustaw nachylenie lub opór, aby zmienić intensywność.","Ćwicz płynnym ruchem, a uchwyty możesz wykorzystać do kontroli tętna."],"tips":["Utrzymuj wyprostowaną sylwetkę i nie garb się.","Nie opieraj całego ciężaru na rękach."]},{"id":"Bicycling_Stationary","n":"Rower stacjonarny","en":"Bicycling, Stationary","p":"cardio","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"min","tags":[],"steps":["Usiądź na rowerze i wyreguluj siodełko do swojego wzrostu.","Wybierz opcję z menu; może być konieczne rozpoczęcie pedałowania, by włączyć urządzenie.","Użyj trybu ręcznego lub wybierz program; wprowadź wiek i wagę, by oszacować kalorie.","Zmieniaj poziom oporu w trakcie treningu.","Uchwyty możesz wykorzystać do kontroli tętna."],"tips":["Siodełko ustaw tak, by noga w dolnym położeniu była lekko ugięta.","Nie garb pleców i nie obciążaj nadgarstków."]},{"id":"Recumbent_Bike","n":"Rower poziomy","en":"Recumbent Bike","p":"cardio","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"beginner","u":"min","tags":[],"steps":["Usiądź na rowerze i wyreguluj siodełko do swojego wzrostu.","Wybierz opcję z menu; może być konieczne rozpoczęcie pedałowania, by włączyć urządzenie.","Użyj trybu ręcznego lub wybierz program; wprowadź wiek i wagę, by oszacować kalorie.","Zmieniaj poziom oporu w trakcie treningu.","Uchwyty możesz wykorzystać do kontroli tętna."],"tips":["Pedałuj płynnie, bez kołysania miednicą.","Plecy opieraj o oparcie, a kolana nie powinny się całkiem prostować."]},{"id":"Rowing_Stationary","n":"Ergometr wioślarski","en":"Rowing, Stationary","p":"cardio","m":["czworogłowe uda"],"m2":["biceps","łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"intermediate","u":"min","tags":[],"steps":["Usiądź na ergometrze, pięty oprzyj o podstawę pedałów i zapnij paski.","Wybierz program, jeśli jest dostępny.","Faza pierwsza: przysuń się do przodu, kolana ugięte przy klatce, tułów lekko pochylony, plecy proste.","Faza druga: odepchnij się nogami, a następnie przyciągnij uchwyt do górnej części brzucha, ściągając łopatki.","Faza powrotu: wyprostuj ramiona, ugnij kolana i przesuń ciało do przodu, wracając do fazy pierwszej."],"tips":["Siłę generuj głównie nogami i biodrami, nie plecami.","Zachowaj proste plecy i nie szarp uchwytu."]},{"id":"Stairmaster","n":"Stepper schodowy","en":"Stairmaster","p":"cardio","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"machine","lvl":"intermediate","u":"min","tags":["kneeStress"],"steps":["Wejdź na steper i wybierz opcję z menu: tryb ręczny lub program.","Wprowadź wiek i wagę, jeśli chcesz oszacować spalone kalorie.","Poruszaj nogami w równym rytmie, wciskając pedały w dół, ale nie do samej podłogi.","Trzymaj się uchwytów, by nie stracić równowagi; możesz też kontrolować nimi tętno."],"tips":["Nie opieraj się całym ciężarem na poręczach.","Trzymaj wyprostowaną sylwetkę i równy rytm."]},{"id":"Battling_Ropes","n":"Liny bojowe (battle ropes)","en":"Battling Ropes","p":"cardio","m":["barki"],"m2":["klatka","przedramiona"],"eq":"other","lvl":"beginner","u":"min","tags":["highIntensity"],"steps":["Przygotuj ciężką linę zakotwiczoną w środku, ok. 5 m od ciebie.","Stań przed liną i chwyć po jednym końcu w każdą dłoń, ramiona opuszczone po bokach.","Szybko unieś jedną rękę do wysokości barku.","Gdy opuszczasz tę rękę, unieś przeciwną.","Kontynuuj naprzemiennie, uderzając linami w górę i w dół najszybciej, jak potrafisz."],"tips":["Stój w lekkim ugięciu kolan i napnij brzuch.","Ruch pochodzi z ramion, nie garb pleców."]},{"id":"Rope_Jumping","n":"Skakanka","en":"Rope Jumping","p":"cardio","m":["czworogłowe uda"],"m2":["łydki","dwugłowe uda"],"eq":"other","lvl":"intermediate","u":"min","tags":["highIntensity","impact","kneeStress"],"steps":["Chwyć po jednym końcu skakanki w każdą dłoń i połóż linę za sobą na podłodze.","Unieś ramiona i przekręć linę nad głową, sprowadzając ją przed siebie.","Gdy lina dotknie podłogi, przeskocz nad nią.","Znajdź tempo, które utrzymasz przez dłuższy czas.","Zmieniaj prędkość i technikę, by urozmaicić trening."],"tips":["Skacz nisko, lądując miękko na przedniej części stopy.","Kręć liną nadgarstkami, a łokcie trzymaj blisko ciała."]},{"id":"Farmers_Walk","n":"Spacer farmera","en":"Farmer's Walk","p":"full","m":["przedramiona"],"m2":["brzuch","pośladki","dwugłowe uda","dolny odc. pleców"],"eq":"dumbbell","lvl":"intermediate","u":"s","tags":[],"steps":["Przygotuj przyrządy do spaceru farmera; mogą to być też ciężkie hantle lub krótkie sztangi.","Stań między przyrządami i chwyć uchwyty.","Podnieś ciężar, pchając piętami w podłoże, z prostymi plecami i uniesioną głową.","Idź krótkimi, szybkimi krokami na wyznaczonym dystansie, zwykle 15–30 m.","Pamiętaj o oddychaniu."],"tips":["Plecy proste, barki cofnięte, bez pochylania się na boki.","Trzymaj uchwyt mocno i nie opuszczaj głowy."]},{"id":"Kettlebell_Thruster","n":"Thruster z kettlem","en":"Kettlebell Thruster","p":"full","m":["barki"],"m2":["czworogłowe uda","triceps"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":["highIntensity","overhead"],"steps":["Zarzuć dwa kettlebelle na barki, prostując nogi i biodra oraz obracając nadgarstki.","Wykonaj przysiad, zginając biodra i kolana, z wyprostowanymi plecami i tułowiem.","Zejdź tak nisko, jak potrafisz, a na dole zmień kierunek.","Wstając i prostując kolana oraz biodra, pchaj przez pięty.","Wykorzystaj pęd z przysiadu, by wycisnąć oba kettlebelle nad głowę.","Wróć z ciężarami na barki i zacznij kolejne powtórzenie."],"tips":["Utrzymuj prosty tułów i nie zapadaj klatki w przysiadzie.","Połącz przysiad z wyciskaniem w jeden płynny ruch."]},{"id":"Kettlebell_Turkish_Get-Up_Squat_style","n":"Tureckie wstawanie","en":"Kettlebell Turkish Get-Up (Squat style)","p":"full","m":["barki"],"m2":["brzuch","łydki","dwugłowe uda","czworogłowe uda"],"eq":"kettlebells","lvl":"intermediate","u":"r","tags":["overhead"],"steps":["Połóż się na plecach i wyciśnij kettlebell nad siebie, prostując łokieć.","Ugnij kolano po stronie ciężaru.","Cały czas utrzymując kettlebell wyprostowany w górze, obróć się na bok i drugą ręką pomóż sobie przejść do pozycji wykroku.","Wolną dłonią podeprzyj się do siadu, a następnie przejdź do stania.","Patrząc na kettlebell, powoli wstań.","Odwróć ruch i wróć do pozycji wyjściowej, po czym powtórz."],"tips":["Ramię z ciężarem cały czas wyprostowane i pionowo nad barkiem.","Wykonuj ruch powoli, kontrolując każdą fazę."]},{"id":"Clean_and_Press","n":"Zarzut i wyciskanie","en":"Clean and Press","p":"full","m":["barki"],"m2":["brzuch","łydki","pośladki","dwugłowe uda"],"eq":"barbell","lvl":"intermediate","u":"r","tags":["axial","highIntensity","overhead"],"steps":["Stań w rozkroku na szerokość barków i ugnij kolana oraz biodra, plecy płaskie.","Chwyć sztangę nachwytem nieco szerzej niż barki, ramiona wyprostowane, łokcie na zewnątrz, sztanga przy goleniach.","Zacznij podciąg, prostując kolana; biodra i barki unoś w tym samym tempie, trzymając sztangę blisko ciała.","Gdy sztanga minie kolana, dynamicznie wyprostuj kostki, kolana i biodra jak do wyskoku oraz wzruszając barkami podciągnij sztangę jak najwyżej.","Wejdź pod sztangę w przysiad, obracając łokcie pod nią, i oprzyj ją na przedniej części barków.","Wstań z tułowiem wyprostowanym i, nie ruszając stóp, wyciśnij sztangę nad głowę, wydychając powietrze.","Opuść sztangę w kontrolowany sposób."],"tips":["Plecy płaskie przez cały ruch, sztanga blisko ciała.","Nie zginaj łokci zbyt wcześnie, najpierw pracują nogi i biodra."]},{"id":"Freehand_Jump_Squat","n":"Przysiad z wyskokiem","en":"Freehand Jump Squat","p":"plyo","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"body only","lvl":"intermediate","u":"r","tags":["highIntensity","impact","kneeStress"],"steps":["Skrzyżuj ramiona na klatce piersiowej i stań w rozkroku na szerokość barków, głowa uniesiona, plecy proste.","Z prostymi plecami i otwartą klatką zrób przysiad, wdychając powietrze, aż uda będą co najmniej równoległe do podłogi.","Odbij się głównie przodem stóp i wyskocz jak najwyżej, wydychając powietrze.","Po lądowaniu od razu zejdź w kolejny przysiad i wyskocz ponownie.","Powtórz zalecaną liczbę powtórzeń."],"tips":["Ląduj miękko, z ugiętymi kolanami, bez wchodzenia kolan do środka.","Nie zaokrąglaj pleców w przysiadzie."]},{"id":"Star_Jump","n":"Wyskok gwiazda","en":"Star Jump","p":"plyo","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda","barki"],"eq":"body only","lvl":"beginner","u":"r","tags":["highIntensity","impact","kneeStress"],"steps":["Stań swobodnie w rozkroku na szerokość barków, ramiona przy ciele.","Zejdź do półprzysiadu.","Wybij się dynamicznie jak najwyżej, wyprostuj całe ciało i rozłóż nogi oraz ramiona na boki.","Przy lądowaniu zbierz kończyny z powrotem i amortyzuj uderzenie nogami."],"tips":["Lądowanie miękkie, na ugiętych nogach.","Napnij brzuch i trzymaj kolana w osi stóp."]},{"id":"Overhead_Slam","n":"Rzut piłką lekarską o ziemię","en":"Overhead Slam","p":"plyo","m":["najszersze grzbietu"],"m2":[],"eq":"medicine ball","lvl":"beginner","u":"r","tags":["highIntensity","impact","overhead"],"steps":["Stań w rozkroku na szerokość barków, trzymając piłkę lekarską oburącz.","Unieś piłkę nad głowę, całkowicie prostując ciało.","Odwróć ruch i z całej siły rzuć piłkę w podłogę tuż przed sobą.","Złap piłkę oburącz po odbiciu i powtórz ruch."],"tips":["Wkładaj w rzut całe ciało, nie tylko ramiona.","Nie zaokrąglaj pleców przy podnoszeniu piłki z podłogi."]},{"id":"Medicine_Ball_Chest_Pass","n":"Podanie piłki lekarskiej sprzed klatki","en":"Medicine Ball Chest Pass","p":"plyo","m":["klatka"],"m2":["barki","triceps"],"eq":"medicine ball","lvl":"beginner","u":"r","tags":["highIntensity"],"steps":["Potrzebny jest partner, a bez niego możesz rzucać o ścianę.","Stań przodem do partnera, trzymając piłkę lekarską oburącz przy tułowiu.","Przyciągnij piłkę do klatki piersiowej, po czym odwróć ruch, prostując łokcie.","W ćwiczeniu sportowym możesz zrobić krok podczas rzutu.","Partner łapie piłkę i odrzuca ją do ciebie; złap ją oburącz na wysokości klatki."],"tips":["Wykonuj dynamiczny, ale kontrolowany rzut.","Trzymaj napięty tułów i stabilną postawę."]},{"id":"Standing_Long_Jump","n":"Skok w dal z miejsca","en":"Standing Long Jump","p":"plyo","m":["czworogłowe uda"],"m2":["łydki","pośladki","dwugłowe uda"],"eq":"body only","lvl":"beginner","u":"r","tags":["highIntensity","impact","kneeStress"],"steps":["Najlepiej wykonuj ćwiczenie na piasku lub miękkim podłożu i przygotuj sposób pomiaru dystansu.","Stań w rozkroku na szerokość barków, w półprzysiadzie.","Zamachnij mocno ramionami i wykonaj przeciwruch nóg, po czym wyskocz do przodu jak najdalej.","Staraj się lądować ze stopami wysuniętymi do przodu, sięgając nogami jak najdalej.","Zmierz odległość od miejsca lądowania do startu i zapisz wynik."],"tips":["Używaj energicznego zamachu ramion.","Ląduj miękko, na ugiętych kolanach."]},{"id":"Arm_Circles","n":"Krążenia ramion","en":"Arm Circles","p":"mobility","m":["barki"],"m2":["kaptury"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Stań prosto i wyciągnij ramiona na boki, równolegle do podłogi, prostopadle do tułowia.","Powoli wykonuj kółka o średnicy ok. 30 cm obiema wyprostowanymi rękami.","Oddychaj normalnie i krąż przez ok. 10 sekund.","Następnie zmień kierunek ruchu."],"tips":["Nie unoś barków do uszu.","Trzymaj ramiona na wysokości barków, nie opuszczaj ich."]},{"id":"Shoulder_Circles","n":"Krążenia barków","en":"Shoulder Circles","p":"mobility","m":["barki"],"m2":["kaptury"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Stań lub usiądź z rozluźnionymi barkami, ramiona luźno opuszczone (lub na kolanach).","Delikatnie zataczaj barkami koła: do przodu, w górę, do tyłu i w dół.","Zmień kierunek ruchu.","Możesz poruszać barkami naprzemiennie lub oboma jednocześnie."],"tips":["Ruchy wykonuj płynnie i w pełnym zakresie.","Nie napinaj szyi."]},{"id":"Standing_Hip_Circles","n":"Krążenia bioder stojąc","en":"Standing Hip Circles","p":"mobility","m":["odwodziciele"],"m2":["przywodziciele"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Stań na jednej nodze, trzymając się pionowej podpory.","Unieś kolano drugiej nogi do kąta 90°.","Otwórz biodro jak najszerzej, wykonując kolanem duże koło.","Wykonuj ruch powoli przez kilka powtórzeń, po czym zmień nogę."],"tips":["Utrzymuj tułów stabilnie, nie przechylaj się na boki.","Rób koła jak największe, ale bez bólu."]},{"id":"Ankle_Circles","n":"Krążenia stóp","en":"Ankle Circles","p":"mobility","m":["łydki"],"m2":[],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Oprzyj się o stabilny przedmiot, np. stojak do przysiadów.","Unieś prawą nogę ok. 5 cm nad podłogę.","Palcem u nogi rysuj duże koło, jedno koło to jedno powtórzenie.","Oddychaj normalnie, a po serii powtórz ruch lewą nogą."],"tips":["Ruch wykonuj ze stopy, bez kołysania całą nogą.","Rób pełne, równe koła w obu kierunkach."]},{"id":"Worlds_Greatest_Stretch","n":"Najlepsze rozciąganie świata","en":"World's Greatest Stretch","p":"mobility","m":["dwugłowe uda"],"m2":["łydki","pośladki","czworogłowe uda"],"eq":"body only","lvl":"intermediate","u":"r","tags":[],"steps":["Zrób wykrok do przodu, przednia stopa płasko na podłodze, tylna na palcach.","Z ugiętymi kolanami zejdź nisko, tak by tylne kolano prawie dotykało podłogi, tułów wyprostowany; wytrzymaj 10–20 sekund.","Połóż rękę po stronie przedniej nogi na podłodze, łokieć przy stopie, a drugą dłoń oprzyj na podłodze równolegle do przedniej nogi; wytrzymaj 10–20 sekund.","Połóż obie dłonie po bokach przedniej stopy, unieś palce stopy i wyprostuj przednią nogę, w razie potrzeby przesuwając tylną; wytrzymaj 10–20 sekund.","Powtórz całą sekwencję na drugą stronę."],"tips":["Utrzymuj prosty tułów w pierwszej fazie.","Rozciągaj się płynnie, bez bólu."]},{"id":"Inchworm","n":"Gąsienica (inchworm)","en":"Inchworm","p":"mobility","m":["dwugłowe uda"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":["wristLoad"],"steps":["Stań ze stopami blisko siebie.","Z prostymi nogami pochyl się i połóż dłonie na podłodze tuż przed sobą.","Powoli przechodź dłońmi do przodu, naprzemiennie, uginając się tylko w biodrach, aż znajdziesz się w pozycji jak do pompki.","Nie ruszając dłońmi, drobnymi kroczkami podchodź stopami w stronę dłoni, utrzymując proste nogi."],"tips":["Nogi trzymaj jak najbardziej wyprostowane.","Napnij brzuch w pozycji pompki i nie opuszczaj bioder."]},{"id":"Cat_Stretch","n":"Koci grzbiet","en":"Cat Stretch","p":"mobility","m":["dolny odc. pleców"],"m2":["środek pleców","kaptury"],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Uklęknij w podporze na dłoniach i kolanach.","Wciągnij brzuch i zaokrąglij kręgosłup, dolne plecy, barki i szyję, opuszczając głowę.","Wytrzymaj 15 sekund."],"tips":["Dłonie ustaw pod barkami, a kolana pod biodrami.","Zaokrąglaj plecy płynnie, oddychając spokojnie."]},{"id":"Dynamic_Chest_Stretch","n":"Dynamiczne otwieranie klatki","en":"Dynamic Chest Stretch","p":"mobility","m":["klatka"],"m2":["środek pleców"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Stań z dłońmi złączonymi, ramiona wyprostowane przed sobą.","Z prostymi ramionami szybko odwiedź je jak najdalej do tyłu i wróć, jak w przesadzonym klaskaniu.","Powtórz 5–10 razy, stopniowo zwiększając tempo."],"tips":["Łokcie trzymaj wyprostowane, nie zginaj ich.","Wyprostuj plecy i nie wyginaj lędźwi."]},{"id":"Front_Leg_Raises","n":"Wymachy nóg w przód","en":"Front Leg Raises","p":"mobility","m":["dwugłowe uda"],"m2":[],"eq":"body only","lvl":"beginner","u":"r","tags":[],"steps":["Stań obok krzesła lub innej podpory, przytrzymując się jedną ręką.","Wymachnij nogą do przodu, trzymając ją prostą.","Kontynuuj ruch w dół i odprowadź nogę do tyłu, na ile pozwala ruchomość.","Powtórz 5–10 razy, po czym zmień nogę."],"tips":["Tułów trzymaj wyprostowany i nie bujaj się.","Wykonuj płynny, kontrolowany wymach."]},{"id":"Torso_Rotation","n":"Skręty tułowia","en":"Torso Rotation","p":"mobility","m":["brzuch"],"m2":[],"eq":"exercise ball","lvl":"beginner","u":"r","tags":[],"steps":["Stań prosto, trzymając piłkę gimnastyczną oburącz.","Wyprostuj ramiona tak, by piłka znajdowała się przed tobą.","Obróć tułów w jedną stronę, śledząc piłkę wzrokiem.","Wróć i obróć tułów w przeciwną stronę.","Powtórz 10–20 razy."],"tips":["Ramiona trzymaj wyprostowane na wysokości klatki.","Biodra trzymaj stabilnie i skręcaj tułów w odcinku piersiowym."]},{"id":"Groiners","n":"Groiners – wykrok z otwarciem bioder","en":"Groiners","p":"mobility","m":["przywodziciele"],"m2":[],"eq":"body only","lvl":"intermediate","u":"r","tags":["hipDeep"],"steps":["Przyjmij pozycję jak do pompki.","Obiema nogami wyskocz do przodu, lądując stopami przy dłoniach, z głową uniesioną.","Wróć do pozycji wyjściowej i od razu powtórz ruch.","Wykonaj 10–20 powtórzeń."],"tips":["Trzymaj głowę uniesioną i plecy proste.","Ląduj stopami jak najbliżej dłoni."]},{"id":"Hamstring_Stretch","n":"Rozciąganie tyłu uda","en":"Hamstring Stretch","p":"stretch","m":["dwugłowe uda"],"m2":[],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Połóż się na plecach z jedną nogą uniesioną w górę, biodro zgięte do 90°.","Drugą nogę trzymaj płasko na podłodze.","Zarzuć pasek, taśmę lub linę na śródstopie uniesionej nogi.","Pociągnij pasek, by poczuć napięcie w łydce i tylnej części uda.","Wytrzymaj 10–30 sekund i powtórz z drugą nogą."],"tips":["Trzymaj kolano prawie proste, ale bez przeprostu.","Rozciągaj do lekkiego napięcia, nie do bólu."]},{"id":"Quad_Stretch","n":"Rozciąganie czworogłowego uda","en":"Quad Stretch","p":"stretch","m":["czworogłowe uda"],"m2":[],"eq":"body only","lvl":"intermediate","u":"s","tags":[],"steps":["Połóż się na boku i zarzuć pasek, linę lub taśmę na górną stopę.","Zegnij kolano i wyprostuj biodro, próbując dotknąć stopą pośladka, trzymając pasek w dłoniach.","Przełóż pasek przez ramię lub nad głowę i delikatnie pociągnij, by zwiększyć rozciągnięcie czworogłowego.","Wytrzymaj 10–20 sekund, po czym zmień stronę."],"tips":["Nie wyginaj dolnych pleców.","Kolana trzymaj blisko siebie."]},{"id":"Kneeling_Hip_Flexor","n":"Rozciąganie zginaczy biodra w klęku","en":"Kneeling Hip Flexor","p":"stretch","m":["czworogłowe uda"],"m2":["czworogłowe uda"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Uklęknij na macie i postaw prawą stopę przed sobą, podeszwą na podłodze.","Lewą nogę wyciągnij do tyłu, grzbietem stopy na podłodze.","Przenieś ciężar ciała do przodu, aż poczujesz rozciąganie w biodrze.","Wytrzymaj 15 sekund, po czym zmień stronę."],"tips":["Tułów trzymaj wyprostowany i napnij pośladek tylnej nogi.","Nie przeginaj lędźwi."]},{"id":"Childs_Pose","n":"Pozycja dziecka","en":"Child's Pose","p":"stretch","m":["dolny odc. pleców"],"m2":["pośladki","środek pleców"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Uklęknij w podporze na dłoniach i kolanach, a następnie wyprowadź dłonie do przodu.","Opuść pośladki na pięty.","Pozwól rękom sunąć po podłodze, aby rozciągnąć cały kręgosłup.","Gdy usiądziesz na piętach, ułóż dłonie przy stopach i rozluźnij się, oddychając w plecy.","Oprzyj czoło na podłodze."],"tips":["Unikaj tej pozycji przy problemach z kolanami.","Oddychaj głęboko i rozluźnij barki."]},{"id":"Lying_Glute","n":"Rozciąganie pośladka leżąc","en":"Lying Glute","p":"stretch","m":["pośladki"],"m2":["odwodziciele"],"eq":"body only","lvl":"expert","u":"s","tags":[],"steps":["Połóż się na plecach, a partner klęka obok ciebie.","Zegnij biodro jednej nogi i unieś ją, obracając tak, by stopa była nad przeciwnym biodrem, a podudzie prostopadle do ciała.","Partner przytrzymuje kolano i kostkę w miejscu.","Spróbuj pchnąć nogę w stronę partnera, który blokuje ruch; trwaj 10–20 sekund.","Całkowicie się rozluźnij, a partner delikatnie dociska kostkę i kolano w stronę twojej klatki."],"tips":["Informuj partnera, gdy rozciągnięcie jest wystarczające.","Nie dopuszczaj do nadmiernego, gwałtownego dociskania."]},{"id":"Calf_Stretch_Hands_Against_Wall","n":"Rozciąganie łydki przy ścianie","en":"Calf Stretch Hands Against Wall","p":"stretch","m":["łydki"],"m2":[],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Stań przodem do ściany w odległości kilku kroków.","Wysuń jedną nogę do przodu w pozycji krokowej.","Pochyl się do przodu i oprzyj dłonie na ścianie, trzymając piętę, biodro i głowę w jednej linii.","Staraj się nie odrywać pięty tylnej nogi od podłogi.","Wytrzymaj 10–20 sekund i zmień stronę."],"tips":["Tylna pięta cały czas dociśnięta do podłogi.","Tylna noga prosta, a ciało w jednej linii."]},{"id":"Chest_And_Front_Of_Shoulder_Stretch","n":"Rozciąganie klatki i przodu barku","en":"Chest And Front Of Shoulder Stretch","p":"stretch","m":["klatka"],"m2":["barki"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Stań ze złączonymi nogami, trzymając drążek lub kij od miotły.","Chwyć kij nachwytem nieco szerzej niż barki i trzymaj go przed sobą.","Ostrożnie unieś kij nad głowę i za głowę."],"tips":["Nie wyginaj dolnych pleców, trzymaj brzuch napięty.","Chwyt szerszy zmniejsza napięcie w barkach."]},{"id":"Overhead_Lat","n":"Rozciąganie najszerszego grzbietu","en":"Overhead Lat","p":"stretch","m":["najszersze grzbietu"],"m2":["triceps"],"eq":"body only","lvl":"expert","u":"s","tags":[],"steps":["Usiądź prosto na podłodze, a partner stoi za tobą.","Unieś jedną rękę prosto w górę i zegnij łokieć, próbując dotknąć dłonią pleców.","Partner trzyma twój triceps i nadgarstek.","Spróbuj przyciągnąć ramię do boku, a partner blokuje ruch; trwaj 10–20 sekund.","Rozluźnij ramię, a partner delikatnie dociska triceps, pogłębiając rozciągnięcie najszerszego grzbietu; wytrzymaj 10–20 sekund i zmień stronę."],"tips":["Partner dociska łagodnie i wolno.","Nie unoś barku do ucha."]},{"id":"Triceps_Stretch","n":"Rozciąganie tricepsa","en":"Triceps Stretch","p":"stretch","m":["triceps"],"m2":["najszersze grzbietu"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Zegnij rękę i sięgnij dłonią za głowę.","Drugą ręką chwyć łokieć i delikatnie go pociągnij.","Wytrzymaj 10–20 sekund, po czym zmień stronę."],"tips":["Nie szarp łokcia, pociągaj spokojnie.","Trzymaj wyprostowane plecy i nie wypychaj głowy."]},{"id":"Spinal_Stretch","n":"Skręt kręgosłupa siedząc","en":"Spinal Stretch","p":"stretch","m":["środek pleców"],"m2":["najszersze grzbietu","dolny odc. pleców","szyja","kaptury"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Usiądź na krześle z prostymi plecami i stopami na podłodze.","Spleć palce za głową, łokcie na zewnątrz, broda opuszczona.","Skręć górną część ciała w jedną stronę, jak najdalej, około 3 razy.","Następnie pochyl się do przodu i skręć tułów, sięgając łokciem do podłogi po wewnętrznej stronie kolana.","Wróć do pozycji wyprostowanej i powtórz na drugą stronę."],"tips":["Skręcaj tułów, nie ciągnij głowy rękami.","Plecy trzymaj długie, nie garb się."]},{"id":"Upper_Back_Stretch","n":"Rozciąganie górnej części pleców","en":"Upper Back Stretch","p":"stretch","m":["środek pleców"],"m2":["środek pleców"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Spleć palce dłoni z kciukami skierowanymi w dół.","Zaokrąglij barki i wyciągnij ręce przed siebie."],"tips":["Pchaj dłonie do przodu, rozszerzając łopatki.","Oddychaj spokojnie i nie napinaj szyi."]},{"id":"Adductor","n":"Rozciąganie przywodzicieli","en":"Adductor","p":"stretch","m":["przywodziciele"],"m2":[],"eq":"foam roll","lvl":"intermediate","u":"s","tags":[],"steps":["Połóż się twarzą do podłogi, jedną nogę oprzyj na wałku do rolowania.","Obróć nogę tak, by wałek przylegał do wewnętrznej strony uda.","Przenieś na wałek tyle ciężaru, ile jesteś w stanie znieść.","Rozluźniając mięśnie wewnętrznej strony uda, przetaczaj się między biodrem a kolanem, zatrzymując się 10–30 sekund na bolesnych punktach.","Powtórz z drugą nogą."],"tips":["Oddychaj spokojnie i rozluźnij mięsień.","Przetaczaj powoli, unikając ostrego bólu."]},{"id":"Quadriceps-SMR","n":"Rolowanie czworogłowego uda","en":"Quadriceps-SMR","p":"stretch","m":["czworogłowe uda"],"m2":[],"eq":"foam roll","lvl":"intermediate","u":"s","tags":[],"steps":["Połóż się twarzą do podłogi, opierając ciężar na dłoniach lub przedramionach.","Połóż wałek pod jednym udem, na czworogłowym, a stopę zawieś nad podłogą.","Rozluźnij nogę najbardziej, jak potrafisz.","Przenieś na wałek tyle ciężaru, ile możesz znieść, i przetaczaj od nad kolana do poniżej biodra.","Zatrzymuj się 10–30 sekund na bolesnych punktach, a następnie zmień nogę."],"tips":["Przetaczaj wolno, bez gwałtownych ruchów.","Utrzymuj napięty brzuch, by nie zapadać się w lędźwiach."]},{"id":"Hug_Knees_To_Chest","n":"Przyciąganie kolan do klatki","en":"Hug Knees To Chest","p":"stretch","m":["dolny odc. pleców"],"m2":["pośladki"],"eq":"body only","lvl":"beginner","u":"s","tags":[],"steps":["Połóż się na plecach i przyciągnij oba kolana do klatki piersiowej.","Chwyć nogi pod kolanami, nie nad nimi, aby nie przeciążać stawów kolanowych.","Powoli przyciągaj kolana w stronę barków.","Ćwiczenie rozciąga także mięśnie pośladków."],"tips":["Obejmuj nogi pod kolanami, nie nad nimi.","Rozluźnij barki i szyję, oddychaj spokojnie."]}];
